# Generated from tools/data/rulebooks/monopoly.json; run tools/compile-rulebooks.rb.
module GameRoomGames
  class Monopoly
    module GeneratedRulebook
      private

      def generated_rule_sections
        [
          rule_section(:journey, GameRoomRules.translate("A journey of buying and collecting rent"),
            GameRoomRules.translate("Two to eight players travel around the board, buy properties and charge visitors rent. Everyone starts with the cash assigned to the chosen board. Your aim is to remain solvent after all the others have gone bankrupt. Owning the most properties is useful, but is not itself a victory condition: you must still be able to meet your payments."),
            GameRoomRules.translate("On your turn, roll two dice and move by their sum. The field you reach determines what happens next: a purchase, rent, a tax, a card or another board instruction. The game moves to the next player once these decisions are settled; there is no separate End turn button. Doubles usually give you another roll, but three doubles in a row send you to jail without making the third move. Jail or a negative cash balance cancels an extra roll.")),
          rule_section(:ownership, GameRoomRules.translate("Buy a street, then complete its colour"),
            GameRoomRules.translate("An unowned street, station or utility may be bought when you land on it. The game gives its name, colour or type, and price. If you have enough cash, choose whether to buy. If you cannot afford it, the purchase is declined automatically. A property you do not buy remains available, unless the auction option sends it to auction."),
            GameRoomRules.translate("Streets belong to colour groups. Once you own every street in a group, you have a complete group: its undeveloped base rent doubles and you can start building there. For example, owning two out of three streets is still incomplete. The holdings lists show how many you own out of the whole group. Stations and utilities form their own sets, but never receive houses or hotels."),
            GameRoomRules.translate("Forbid buying properties on the first board round is off by default. If enabled, each player must first pass Start once before an unowned field offers them a purchase. This is your own first trip around the board, not the first circuit of turns taken by the table.")),
          rule_section(:auctions, GameRoomRules.translate("When a purchase becomes an auction"),
            GameRoomRules.translate("Put unsold properties up for auction is off by default. Turn it on if you want a declined purchase to be offered to the active players through bidding. Players take turns bidding or passing. Passing withdraws you from this auction. The remaining highest bidder pays their final bid and receives the property; the printed purchase price is not the amount automatically charged."),
            GameRoomRules.translate("Auction decision time is the number of seconds for one bid or pass. Zero, the default, gives unlimited time. A positive limit starts afresh for the next bidder after every accepted decision; exceeding it means an automatic pass. B lets you enter a total purchase bid, above the current bid and within your cash. Enter or G accepts the suggested next bid. You cannot save the game during an auction.")),
          rule_section(:rent, GameRoomRules.translate("Rent follows the deed"),
            GameRoomRules.translate("Landing on someone else's chargeable property makes you pay its owner. For a street, the amount depends on its rent schedule, colour group and buildings. Stations depend on how many stations the owner has. Utilities also use the dice total. A mortgaged property charges no rent. Open your holdings with V or another player's holdings with Shift+V, then press Enter on a property to check its current rent. For a utility, the description gives the multiplier of the visitor's dice total rather than using an earlier roll."),
            GameRoomRules.translate("Pay rents automatically is enabled by default. Without it, the owner decides whether to request or waive each eligible rent, and the visitor's move waits for this decision. Do not collect rent while in jail is a separate option, off by default. Enabling it removes rent income for an owner who is currently imprisoned; it does not remove their ownership.")),
          rule_section(:building, GameRoomRules.translate("Develop a group evenly"),
            GameRoomRules.translate("Manage your properties on your own turn before rolling, or while resolving your debt on that turn. To build, you need the complete colour group and no mortgages in that group. Add houses to the least developed streets first. In a three-street group you can reach one house on each before putting a second on any street. Four houses may be replaced by a hotel, the fifth development level."),
            GameRoomRules.translate("Selling reverses that process: remove buildings from the most developed streets and receive half their purchase price. The bank normally has 32 houses and 12 hotels on a 40-field board, or 48 houses and 18 hotels on a 60-field board. Turning a hotel back into four houses needs those houses to be available. If there are too few, the list explicitly offers selling all buildings in the colour group instead, still at half price."),
            GameRoomRules.translate("The building and selling lists show the colour, existing buildings and cost or proceeds. Confirm an operation with Enter and stay in the list to continue managing properties. If no operation is possible, the game explains why instead of making you select a building you cannot buy.")),
          rule_section(:mortgages, GameRoomRules.translate("Release cash without losing ownership"),
            GameRoomRules.translate("A mortgage pays you the property's mortgage value, while the property remains yours and stops earning rent. Before mortgaging a street, sell every building in its colour group. To remove the mortgage later, pay the mortgage amount plus 10%, rounded up to a whole money unit. For example, a mortgage of 100 costs 110 to clear. The lists display the actual payment before confirmation.")),
          rule_section(:trading, GameRoomRules.translate("Make an offer to another player"),
            GameRoomRules.translate("A trade may combine properties and cash from either side. E opens the players; Enter chooses a partner and announces that you are preparing an offer. It does not send an empty offer. In the form, enter the two cash amounts and choose properties from the two checkbox lists. Arrows move within a property list, while Tab moves between the form's sections. Send proposal submits the complete offer; Escape returns to the player list."),
            GameRoomRules.translate("Nothing changes hands until the recipient accepts. Both sides must still afford their payments and own the offered properties. Mortgaged properties and streets in a group with buildings cannot be traded. A bot may decline an apparently fair face-value purchase because the property completes or protects an important group; the printed price is not a promise that the owner will sell.")),
          rule_section(:debt, GameRoomRules.translate("When you owe more cash than you have"),
            GameRoomRules.translate("In Power Games, a negative balance ends your current turn. The other players take their turns before your next one begins. Then you can sell buildings, mortgage properties or arrange a trade to cover the shortfall. Roll remains the main action, but tells you how much is missing instead of rolling while the balance is negative. A payment charged outside your turn does not interrupt the current player's move."),
            GameRoomRules.translate("While in debt you may declare bankruptcy. It happens automatically on your own turn when you have no buildings left to sell and no property available to mortgage. A merely possible trade does not postpone this. If another player is your creditor, they receive your remaining properties and held jail cards, with buildings liquidated at half price. For a debt to the bank, the properties return to the bank. Bankruptcy ends your participation; the last player still solvent wins.")),
          rule_section(:jail, GameRoomRules.translate("Visiting jail is not being imprisoned"),
            GameRoomRules.translate("You are imprisoned only when a field, a card or three consecutive doubles sends you there. Simply stopping on the jail field is a visit. Before a prison roll, you may pay the exit fee or use a held jail card. Otherwise you have up to three turns to roll doubles. Successful doubles release you and move you by the roll, without an extra turn. After the third failed attempt, you pay and move by that roll."),
            GameRoomRules.translate("Lucky double one is off by default. If enabled, rolling two ones on a normal moving roll awards a quarter of the board's Start salary. The jail exit fee uses the same quarter-salary scale, rounded to whole money units.")),
          rule_section(:events, GameRoomRules.translate("Start, Free Parking and cards"),
            GameRoomRules.translate("Passing Start pays the board's salary. Double salary on Start, enabled by default, doubles that payment only when you land exactly on Start. Free parking jackpot is also on by default. Its pool starts at zero and collects eligible taxes and bank fees. Landing on Free Parking takes the whole pool and resets it to zero. Rent, trades, purchases, construction and mortgage transactions do not add to it. With the option off, Free Parking pays nothing."),
            GameRoomRules.translate("Chance and Community Chest use separate shuffled decks. A card may change money, move you, charge for buildings, send you to jail or give a retained jail-exit card. A retained card is unavailable in its deck until returned or used. Supplementary cards is enabled by default; turning it off removes the additional Power Games events, not the normal decks. Payments and destinations are adapted to the board you chose.")),
          rule_section(:boards, GameRoomRules.translate("Regional boards have their own figures"),
            GameRoomRules.translate("The default board is American / Atlantic City. A different board can change names, layout, currency, starting cash, Start salary and property economics. Larger boards also have more colour groups, stations and utilities. The profiles below are generated from the boards actually used by Power Games. Inspect individual deeds for purchase prices, rent levels and mortgage values."),
            GameRoomRules.translate("The Polish board is a custom Warsaw board. Regional data combines observed layouts and deed values with adapted salaries, fees, building costs and event cards; it is not a guarantee of matching every commercial or QC edition. In these profiles, Income Tax is one Start salary and Luxury Tax half a salary.")),
          board_profile_rules,
          rule_section(:controls, GameRoomRules.translate("Game keyboard shortcuts"),
            GameRoomRules.translate("Arrows: choose the current action or property."),
            GameRoomRules.translate("Enter: confirm the selected action."),
            GameRoomRules.translate("Escape: close the current list."),
            GameRoomRules.translate("I: read player positions and field numbers."),
            GameRoomRules.translate("T: read the turn and phase."),
            GameRoomRules.translate("C: read your cash."),
            GameRoomRules.translate("S: read player finances."),
            GameRoomRules.translate("F: read the current property's deed."),
            GameRoomRules.translate("D: browse unowned properties."),
            GameRoomRules.translate("Shift+D: browse the board."),
            GameRoomRules.translate("V: browse your properties."),
            GameRoomRules.translate("Shift+V: browse other players' properties."),
            GameRoomRules.translate("H: build houses or hotels."),
            GameRoomRules.translate("Shift+H: sell buildings."),
            GameRoomRules.translate("K: mortgage properties."),
            GameRoomRules.translate("Shift+K: unmortgage properties."),
            GameRoomRules.translate("E: prepare a trade."),
            GameRoomRules.translate("A: accept an incoming offer."),
            GameRoomRules.translate("R: reject an incoming offer."),
            GameRoomRules.translate("B: during an auction, enter your own total bid."),
            GameRoomRules.translate("G: during an auction, accept the suggested bid."),
            GameRoomRules.translate("Space: request rent when manual collection is available."),
            GameRoomRules.translate("P: pay to leave jail."),
            GameRoomRules.translate("J: use a get-out-of-jail card."))
        ]
      end

      def localized_rule_sections
        case GameRoomLocalization.primary_language
        when "cs"
          [
            rule_section(:aim, "C\u00EDl hry",
              "V Monopoly kupuje\u0161 nemovitosti a vyb\u00EDr\u00E1\u0161 n\u00E1jemn\u00E9 od hr\u00E1\u010D\u016F, kte\u0159\u00ED na nich zastav\u00ED. Z\u00E1rove\u0148 si pot\u0159ebuje\u0161 nechat pen\u00EDze na vlastn\u00ED platby. Vyhraje posledn\u00ED hr\u00E1\u010D, kter\u00FD nezbankrotuje.",
              "Hraj\u00ED dva a\u017E osm hr\u00E1\u010D\u016F. Z\u00E1kladn\u00ED deska Atlantic City m\u00E1 \u010Dty\u0159icet pol\u00ED. V\u0161ichni za\u010D\u00EDnaj\u00ED na Startu s 1500 dolary."),
            rule_section(:turn, "Hod kostkami a pohyb",
              "Na za\u010D\u00E1tku tahu vyber hod kostkami a potvr\u010F Enterem. Dv\u011B kostky ur\u010D\u00ED po\u010Det pol\u00ED, o kter\u00FD postoup\u00ED\u0161. Dal\u0161\u00ED akce z\u00E1le\u017E\u00ED na c\u00EDlov\u00E9m poli: nap\u0159\u00EDklad koup\u00ED\u0161 nemovitost nebo zaplat\u00ED\u0161 majiteli n\u00E1jemn\u00E9.",
              "Dostupn\u00E9 akce vyb\u00EDr\u00E1\u0161 \u0161ipkami a potvrzuje\u0161 Enterem. Po vy\u0159\u00EDzen\u00ED pole p\u0159ijde na \u0159adu dal\u0161\u00ED hr\u00E1\u010D.",
              "Dvojice stejn\u00FDch \u010D\u00EDsel d\u00E1v\u00E1 po pohybu a vy\u0159\u00EDzen\u00ED pole dal\u0161\u00ED hod. T\u0159et\u00ED dvojice za sebou t\u011B v\u0161ak po\u0161le do v\u011Bzen\u00ED bez t\u0159et\u00EDho pohybu. V\u011Bzen\u00ED i vznik dluhu dal\u0161\u00ED hody ukon\u010D\u00ED.",
              "Polohy hr\u00E1\u010D\u016F p\u0159e\u010Dte I, desku prohl\u00E9dne\u0161 pomoc\u00ED Shift+D a vlastn\u00ED hotovost zjist\u00ED\u0161 kl\u00E1vesou C."),
            rule_section(:buying, "N\u00E1kup nemovitost\u00ED",
              "Na voln\u00E9 nemovitosti si m\u016F\u017Ee\u0161 vybrat n\u00E1kup za uvedenou cenu. Zvol n\u00E1kup \u0161ipkami a potvr\u010F Enterem, nebo vyber odm\u00EDtnut\u00ED. Bez dostate\u010Dn\u00E9 hotovosti se n\u00E1kup p\u0159esko\u010D\u00ED. Nekoupen\u00E1 nemovitost z\u016Fstane voln\u00E1.",
              "Nemovitosti jsou t\u0159\u00ED druh\u016F:",
              "- Ulice tvo\u0159\u00ED barevn\u00E9 skupiny. Cel\u00E1 skupina umo\u017En\u00ED vy\u0161\u0161\u00ED n\u00E1jemn\u00E9 a stavbu dom\u016F.",
              "- N\u00E1dra\u017E\u00ED vyb\u00EDraj\u00ED vy\u0161\u0161\u00ED n\u00E1jemn\u00E9, \u010D\u00EDm v\u00EDce jich m\u00E1 stejn\u00FD majitel.",
              "- Podniky, nap\u0159\u00EDklad elektr\u00E1rna a vod\u00E1rna, odvozuj\u00ED n\u00E1jemn\u00E9 od hodu kostkami. N\u00E1sobitel z\u00E1le\u017E\u00ED na po\u010Dtu podnik\u016F majitele.",
              "Kartu nemovitosti pod figurkou p\u0159e\u010Dte F. Uv\u00E1d\u00ED cenu, n\u00E1jemn\u00E9, stavbu i z\u00E1stavu. Vlastn\u00ED nemovitosti prohl\u00E9dne\u0161 pomoc\u00ED V, ciz\u00ED pomoc\u00ED Shift+V. V seznamu vyber \u0161ipkami a Enterem otev\u0159i podrobnosti."),
            rule_section(:rent, "N\u00E1jemn\u00E9",
              "Za zastaven\u00ED na ciz\u00ED nemovitosti plat\u00ED\u0161 majiteli n\u00E1jemn\u00E9, b\u011B\u017En\u011B automaticky. Na vlastn\u00EDm ani zastaven\u00E9m pozemku se neplat\u00ED.",
              "U ulic ur\u010Duje n\u00E1jemn\u00E9 karta a po\u010Det budov. Vlastn\u00ED-li hr\u00E1\u010D celou barvu, nezastav\u011Bn\u00E1 ulice m\u00E1 dvojn\u00E1sobn\u00E9 z\u00E1kladn\u00ED n\u00E1jemn\u00E9. Domy a hotely ho pak zvy\u0161uj\u00ED podle dal\u0161\u00EDch sazeb."),
            rule_section(:events, "Start, dan\u011B a karty ud\u00E1lost\u00ED",
              "Za pr\u016Fchod Startem dostane\u0161 200 dolar\u016F. P\u0159esn\u00E9 zastaven\u00ED na n\u011Bm p\u0159inese 400.",
              "N\u011Bkter\u00E1 pole nelze koupit:",
              "- Da\u0148 z p\u0159\u00EDjmu stoj\u00ED 200 dolar\u016F, da\u0148 z luxusu 100.",
              "- Bezplatn\u00E9 parkov\u00E1n\u00ED vyplat\u00ED cel\u00FD naspo\u0159en\u00FD bank. P\u0159it\u00E9kaj\u00ED do n\u011Bj dan\u011B a poplatky bance z karet nebo za opu\u0161t\u011Bn\u00ED v\u011Bzen\u00ED. Po vyplacen\u00ED za\u010D\u00EDn\u00E1 znovu od nuly.",
              "- \u0160ance a Pokladna spust\u00ED kartu ud\u00E1losti. Hra jej\u00ED \u00FA\u010Dinek p\u0159e\u010Dte a hned provede.",
              "Karty mohou m\u00EDt tyto \u00FA\u010Dinky:",
              "- P\u0159idaj\u00ED pen\u00EDze z banky nebo ulo\u017E\u00ED platbu.",
              "- Nechaj\u00ED t\u011B platit ostatn\u00EDm hr\u00E1\u010D\u016Fm nebo od ka\u017Ed\u00E9ho n\u011Bco vybrat.",
              "- Opravy \u00FA\u010Dtuj\u00ED podle tv\u00FDch dom\u016F a hotel\u016F.",
              "- P\u0159esunou t\u011B na jin\u00E9 pole. Tam b\u011B\u017En\u011B plat\u00ED n\u00E1kup, n\u00E1jemn\u00E9 \u010Di da\u0148, leda\u017Ee karta \u0159\u00EDk\u00E1 n\u011Bco jin\u00E9ho.",
              "- Po\u0161lou t\u011B do v\u011Bzen\u00ED.",
              "- Kartu pro opu\u0161t\u011Bn\u00ED v\u011Bzen\u00ED si nech\u00E1\u0161 na pozd\u011Bji.",
              "N\u011Bkter\u00E9 p\u0159esuny upravuj\u00ED i n\u00E1jemn\u00E9:",
              "- Cesta na nejbli\u017E\u0161\u00ED n\u00E1dra\u017E\u00ED zdvojn\u00E1sob\u00ED jeho n\u00E1jemn\u00E9.",
              "- U nejbli\u017E\u0161\u00EDho podniku zaplat\u00ED\u0161 desetin\u00E1sobek nov\u00E9ho hodu dv\u011Bma kostkami.",
              "N\u00E1kupy nemovitost\u00ED a budov, z\u00E1stavy ani platby mezi hr\u00E1\u010Di bank parkov\u00E1n\u00ED nezv\u011Bt\u0161uj\u00ED."),
            rule_section(:building, "Stavba dom\u016F a hotel\u016F",
              "Majetek spravuje\u0161 ve sv\u00E9m tahu p\u0159ed hodem. Stav\u011Bt se d\u00E1 jen na ulic\u00EDch a mus\u00ED\u0161 splnit v\u0161echny podm\u00EDnky:",
              "- Vlastnit celou barevnou skupinu.",
              "- Nem\u00EDt v t\u00E9to skupin\u011B \u017E\u00E1dnou zastavenou ulici.",
              "- M\u00EDt hotovost na stavbu.",
              "Pomoc\u00ED H otev\u0159i mo\u017En\u00E9 stavby, \u0161ipkami vyber ulici a potvr\u010F Enterem. Ka\u017Ed\u00E9 potvrzen\u00ED p\u0159id\u00E1 jednu budovu za uvedenou cenu.",
              "Stav\u00ED se rovnom\u011Brn\u011B: nejprve jeden d\u016Fm na ka\u017Ed\u00E9 ulici skupiny, pak druh\u00E9 domy a tak d\u00E1le a\u017E do \u010Dty\u0159. Dal\u0161\u00ED stavba nahrad\u00ED \u010Dty\u0159i domy hotelem.",
              "Banka m\u00E1 32 dom\u016F a 12 hotel\u016F. Pokud pot\u0159ebn\u00E9 budovy dojdou, mus\u00ED\u0161 po\u010Dkat na jejich n\u00E1vrat. P\u0159i stavb\u011B hotelu se nahrazen\u00E9 \u010Dty\u0159i domy vr\u00E1t\u00ED do z\u00E1soby."),
            rule_section(:selling, "Prodej budov",
              "\u010C\u00E1st pen\u011Bz z\u00EDsk\u00E1\u0161 zp\u011Bt pomoc\u00ED Shift+H. Ze seznamu vyber budovu \u0161ipkami a potvr\u010F Enterem. Prodej vrac\u00ED polovinu stavebn\u00ED ceny.",
              "I prod\u00E1vat mus\u00ED\u0161 rovnom\u011Brn\u011B, od ulic s nejv\u011Bt\u0161\u00EDm po\u010Dtem budov. Prodan\u00FD hotel se b\u011B\u017En\u011B zm\u011Bn\u00ED na \u010Dty\u0159i domy.",
              "Nem\u00E1-li banka pot\u0159ebn\u00E9 \u010Dty\u0159i domy, m\u016F\u017Ee\u0161 m\u00EDsto toho zvolit prodej v\u0161ech budov cel\u00E9 barvy. Dostane\u0161 polovinu jejich stavebn\u00EDch n\u00E1klad\u016F."),
            rule_section(:mortgages, "Z\u00E1stavy",
              "Z\u00E1stava p\u0159inese pen\u00EDze z banky, ani\u017E ztrat\u00ED\u0161 vlastnictv\u00ED. Stiskni K, vyber nemovitost a potvr\u010F Enterem. Dostane\u0161 jej\u00ED z\u00E1stavn\u00ED hodnotu, ale p\u0159estane vyn\u00E1\u0161et n\u00E1jemn\u00E9.",
              "P\u0159ed zastaven\u00EDm ulice mus\u00ED\u0161 prodat v\u0161echny budovy cel\u00E9 jej\u00ED barevn\u00E9 skupiny.",
              "Z\u00E1stavu vyplat\u00ED\u0161 pomoc\u00ED Shift+K: vyber nemovitost a potvr\u010F Enterem. Zaplat\u00ED\u0161 z\u00E1stavn\u00ED hodnotu plus deset procent, zaokrouhleno nahoru na celou jednotku. Z\u00E1stava 100 tedy stoj\u00ED 110. Potom nemovitost znovu vyn\u00E1\u0161\u00ED n\u00E1jemn\u00E9."),
            rule_section(:trading, "Obchodov\u00E1n\u00ED mezi hr\u00E1\u010Di",
              "Nemovitost lze z\u00EDskat i obchodem. Ve sv\u00E9m tahu p\u0159ed hodem stiskni E, vyber partnera \u0161ipkami a potvr\u010F Enterem.",
              "V nab\u00EDdce vypln\u00ED\u0161, kolik pen\u011Bz d\u00E1v\u00E1\u0161 a po\u017Eaduje\u0161. Tabem p\u0159ejde\u0161 na seznamy nemovitost\u00ED obou stran. Proch\u00E1zej je \u0161ipkami a mezern\u00EDkem ozna\u010D ty, kter\u00E9 do obchodu pat\u0159\u00ED. Vym\u011Bnit lze v\u00EDce nemovitost\u00ED i s doplatkem.",
              "Hotovou nab\u00EDdku ode\u0161li tla\u010D\u00EDtkem pro odesl\u00E1n\u00ED n\u00E1vrhu: p\u0159ejdi na n\u011Bj Tabem a potvr\u010F Enterem. Partner p\u0159ijme pomoc\u00ED A nebo odm\u00EDtne pomoc\u00ED R. Pen\u00EDze a vlastnictv\u00ED p\u0159ejdou a\u017E p\u0159ijet\u00EDm.",
              "Obchod m\u00E1 tato omezen\u00ED:",
              "- Nelze p\u0159ev\u00E9st zastavenou nemovitost.",
              "- Nelze p\u0159ev\u00E9st ulici ze skupiny, na kter\u00E9 je\u0161t\u011B stoj\u00ED by\u0165 jedin\u00E1 budova. Nejd\u0159\u00EDv mus\u00ED zmizet z\u00E1stavba cel\u00E9 barvy.",
              "- Ob\u011B strany mus\u00ED b\u00FDt schopn\u00E9 zaplatit svou \u010D\u00E1st. Zapo\u010D\u00EDtaj\u00ED se i pen\u00EDze p\u0159ijat\u00E9 v t\u00E9m\u017Ee obchodu."),
            rule_section(:jail, "V\u011Bzen\u00ED",
              "B\u011B\u017En\u00E9 zastaven\u00ED na v\u011Bzen\u00ED je jen n\u00E1v\u0161t\u011Bva. Trest nastane a\u017E odesl\u00E1n\u00EDm z pole, kartou nebo t\u0159et\u00ED dvojic\u00ED za sebou. Odesl\u00E1n\u00ED ukon\u010D\u00ED tah a nep\u0159inese v\u00FDplatu za Start.",
              "Na za\u010D\u00E1tku tahu ve v\u011Bzen\u00ED m\u00E1\u0161 t\u0159i mo\u017Enosti:",
              "- P zaplat\u00ED 50 dolar\u016F; potom norm\u00E1ln\u011B hod\u00ED\u0161 a postoup\u00ED\u0161.",
              "- J pou\u017Eije dr\u017Eenou kartu pro opu\u0161t\u011Bn\u00ED v\u011Bzen\u00ED; potom tak\u00E9 norm\u00E1ln\u011B hod\u00ED\u0161.",
              "- Enterem rovnou zkus\u00ED\u0161 hodit dvojici. M\u00E1\u0161 na to t\u0159i po sob\u011B jdouc\u00ED tahy.",
              "Dvojice t\u011B osvobod\u00ED a posune o sou\u010Det, ned\u00E1v\u00E1 ale dal\u0161\u00ED hod. T\u0159et\u00ED ne\u00FAsp\u011B\u0161n\u00FD pokus vy\u017Eaduje zaplatit 50 a potom postoupit podle pr\u00E1v\u011B hozen\u00E9ho v\u00FDsledku.",
              "Ve v\u011Bzen\u00ED b\u011B\u017En\u011B d\u00E1l vyb\u00EDr\u00E1\u0161 n\u00E1jemn\u00E9 a p\u0159ed hodem sm\u00ED\u0161 spravovat majetek."),
            rule_section(:debt, "Dluh a bankrot",
              "Platba vy\u0161\u0161\u00ED ne\u017E hotovost vytvo\u0159\u00ED dluh. Stane-li se to p\u0159i tv\u00E9m pohybu, tah skon\u010D\u00ED. Dluh \u0159e\u0161\u00ED\u0161 v p\u0159\u00ED\u0161t\u00EDm vlastn\u00EDm tahu p\u0159ed dal\u0161\u00EDm hodem.",
              "Na splacen\u00ED m\u016F\u017Ee\u0161 prodat budovy, zastavit nemovitosti nebo z\u00EDskat pen\u00EDze obchodem. Po \u00FApln\u00E9m zaplacen\u00ED sm\u00ED\u0161 zase h\u00E1zet.",
              "Kl\u00E1vesou B m\u016F\u017Ee\u0161 p\u0159i dluhu s\u00E1m vyhl\u00E1sit bankrot. Automaticky zbankrotuje\u0161, pokud na sv\u00E9m tahu dlu\u017E\u00ED\u0161 a u\u017E nem\u00E1\u0161 \u017E\u00E1dnou budovu k prodeji ani nemovitost k zastaven\u00ED.",
              "Bankrot t\u011B vy\u0159ad\u00ED. Dlu\u017E\u00ED\u0161-li hr\u00E1\u010Di, dostane zb\u00FDvaj\u00EDc\u00ED nemovitosti a karty pro opu\u0161t\u011Bn\u00ED v\u011Bzen\u00ED, budovy se vypo\u0159\u00E1daj\u00ED za polovinu ceny. P\u0159i dluhu bance se nemovitosti vr\u00E1t\u00ED bance."),
            rule_section(:ending, "Konec hry",
              "Posledn\u00ED hr\u00E1\u010D bez bankrotu v\u00EDt\u011Bz\u00ED. Pr\u016Fb\u011B\u017En\u00E9 finance v\u0161ech porovn\u00E1\u0161 kl\u00E1vesou S."),
            rule_section(:boards, "Jin\u00E9 desky",
              "P\u0159ed hrou m\u016F\u017Ee\u0161 m\u00EDsto Atlantic City zvolit jinou desku. Li\u0161\u00ED se n\u00E1zvy a po\u010Dty pol\u00ED, m\u011Bna, barevn\u00E9 skupiny, po\u010D\u00E1te\u010Dn\u00ED hotovost i v\u00FDplata za Start.",
              "V\u011Bt\u0161\u00ED desky maj\u00ED tak\u00E9 v\u00EDce budov v bance. Ceny, n\u00E1jemn\u00E9 a stavebn\u00ED n\u00E1klady zjist\u00ED\u0161 z karet nemovitost\u00ED stejn\u011B jako b\u011B\u017En\u011B.",
              "N\u011Bkter\u00E9 platby se odvozuj\u00ED od v\u00FDplaty za Start:",
              "- Da\u0148 z p\u0159\u00EDjmu \u010Din\u00ED jednu v\u00FDplatu.",
              "- Da\u0148 z luxusu polovinu.",
              "- Opu\u0161t\u011Bn\u00ED v\u011Bzen\u00ED \u010Dtvrtinu.",
              "Kompletn\u00ED barvy, rovnom\u011Brn\u00E1 stavba, z\u00E1stavy a bankrot maj\u00ED stejn\u00E1 pravidla."),
            rule_section(:auctions, "Dra\u017Eby",
              "B\u011B\u017En\u011B nekoupen\u00E1 nemovitost z\u016Fst\u00E1v\u00E1 voln\u00E1. P\u0159ed hrou m\u016F\u017Ee\u0161 zapnout jej\u00ED dra\u017Ebu. P\u0159ihazovat postupn\u011B sm\u011Bj\u00ED v\u0161ichni dosud hraj\u00EDc\u00ED, v\u010Detn\u011B hr\u00E1\u010De, kter\u00FD n\u00E1kup odm\u00EDtl.",
              "Na \u0159ad\u011B m\u016F\u017Ee\u0161 zv\u00FD\u0161it nebo odstoupit. G pod\u00E1 navr\u017Eenou vy\u0161\u0161\u00ED nab\u00EDdku. Vlastn\u00ED \u010D\u00E1stku zad\u00E1\u0161 p\u0159es B a potvrd\u00ED\u0161 Enterem. Zad\u00E1v\u00E1\u0161 celkovou cenu, nikoli rozd\u00EDl oproti p\u0159edchoz\u00ED nab\u00EDdce.",
              "Nab\u00EDdka mus\u00ED p\u0159es\u00E1hnout sou\u010Dasnou a vej\u00EDt se do hotovosti. Odstoupen\u00ED vyber \u0161ipkami ze seznamu akc\u00ED a potvr\u010F Enterem. Do stejn\u00E9 dra\u017Eby se pak u\u017E nevr\u00E1t\u00ED\u0161.",
              "Jakmile nejvy\u0161\u0161\u00ED nab\u00EDdku nikdo nezv\u00FD\u0161\u00ED, jej\u00ED autor koup\u00ED nemovitost za tuto \u010D\u00E1stku. Bez jedin\u00E9 nab\u00EDdky z\u016Fstane bance.",
              "Pro ka\u017Ed\u00E9 rozhodnut\u00ED lze nastavit \u010Das. Bez odpov\u011Bdi odstoup\u00ED\u0161; ka\u017Ed\u00FD dal\u0161\u00ED dra\u017Eitel dost\u00E1v\u00E1 sv\u016Fj pln\u00FD \u010Das. Nula omezen\u00ED vyp\u00EDn\u00E1."),
            rule_section(:purchase_variant, "N\u00E1kup a\u017E po prvn\u00EDm okruhu",
              "Lze zak\u00E1zat n\u00E1kupy b\u011Bhem prvn\u00EDho okruhu. Pak sm\u00ED\u0161 kupovat voln\u00E1 pole, na kter\u00E1 vstoup\u00ED\u0161, teprve po sv\u00E9m prvn\u00EDm pr\u016Fchodu Startem."),
            rule_section(:rent_variants, "Varianty n\u00E1jemn\u00E9ho",
              "P\u0159ed hrou lze zm\u011Bnit dv\u011B pravidla:",
              "- Bez automatick\u00E9ho v\u00FDb\u011Bru mus\u00ED n\u00E1jemn\u00E9 po\u017Eadovat majitel mezern\u00EDkem. M\u016F\u017Ee se ho tak\u00E9 vzd\u00E1t volbou \u0161ipkami a Enterem. Hra na jeho rozhodnut\u00ED \u010Dek\u00E1.",
              "- Lze zak\u00E1zat vyb\u00EDr\u00E1n\u00ED n\u00E1jemn\u00E9ho uv\u011Bzn\u011Bn\u00FDm majitelem. Ostatn\u00ED pak jeho nemovitosti nav\u0161t\u011Bvuj\u00ED zdarma a\u017E do jeho propu\u0161t\u011Bn\u00ED."),
            rule_section(:event_variants, "Varianty v\u00FDplat a ud\u00E1lost\u00ED",
              "P\u0159ed za\u010D\u00E1tkem lze upravit tak\u00E9 n\u00E1sleduj\u00EDc\u00ED:",
              "- Vypnut\u00E9 spo\u0159en\u00ED na parkov\u00E1n\u00ED znamen\u00E1, \u017Ee pole nic nevyplat\u00ED a bankovn\u00ED poplatky se do n\u011Bj neodkl\u00E1daj\u00ED.",
              "- Bez dvojit\u00E9 v\u00FDplaty dostane\u0161 za p\u0159esn\u00FD Start stejn\u011B jako za pr\u016Fchod.",
              "- \u0160\u0165astn\u00E1 dvojice jedni\u010Dek p\u0159id\u00E1 pr\u00E9mii ve v\u00FD\u0161i \u010Dtvrtiny v\u00FDplaty za Start, na Atlantic City 50 dolar\u016F. B\u011B\u017En\u011B je vypnut\u00E1.",
              "- Vypnut\u00ED dopl\u0148kov\u00FDch karet odstran\u00ED z obou bal\u00ED\u010Dk\u016F pen\u011B\u017En\u00ED ud\u00E1losti p\u0159idan\u00E9 v Power Games. Ostatn\u00ED karty \u0160ance a Pokladny z\u016Fstanou."),
            rule_section(:controls, "Kl\u00E1vesov\u00E9 zkratky",
              "\u0160ipky: vybrat akci nebo nemovitost.",
              "Enter: prov\u00E9st vybranou akci.",
              "Escape: zav\u0159\u00EDt seznam.",
              "I: p\u0159e\u010D\u00EDst polohy hr\u00E1\u010D\u016F a \u010D\u00EDsla pol\u00ED.",
              "T: ozn\u00E1mit hr\u00E1\u010De na \u0159ad\u011B a \u010Dekaj\u00EDc\u00ED rozhodnut\u00ED.",
              "C: p\u0159e\u010D\u00EDst vlastn\u00ED hotovost.",
              "S: p\u0159e\u010D\u00EDst finance hr\u00E1\u010D\u016F.",
              "F: p\u0159e\u010D\u00EDst kartu nemovitosti pod figurkou.",
              "D: prohl\u00E9dnout voln\u00E9 nemovitosti.",
              "Shift+D: prohl\u00E9dnout celou desku.",
              "V: prohl\u00E9dnout vlastn\u00ED nemovitosti.",
              "Shift+V: prohl\u00E9dnout ciz\u00ED nemovitosti.",
              "H: otev\u0159\u00EDt mo\u017En\u00E9 stavby.",
              "Shift+H: otev\u0159\u00EDt budovy k prodeji.",
              "K: otev\u0159\u00EDt nemovitosti k zastaven\u00ED.",
              "Shift+K: otev\u0159\u00EDt z\u00E1stavy k vyplacen\u00ED.",
              "E: vybrat hr\u00E1\u010De a p\u0159ipravit obchod.",
              "A: p\u0159ijmout nab\u00EDdku obchodu.",
              "R: odm\u00EDtnout nab\u00EDdku obchodu.",
              "B: p\u0159i vlastn\u00EDm dluhu vyhl\u00E1sit bankrot, p\u0159i dra\u017Eb\u011B zadat vlastn\u00ED nab\u00EDdku.",
              "G: p\u0159i dra\u017Eb\u011B podat navr\u017Eenou nab\u00EDdku.",
              "Mezern\u00EDk: vybrat n\u00E1jemn\u00E9 p\u0159i ru\u010Dn\u00EDm v\u00FDb\u011Bru.",
              "P: zaplatit za opu\u0161t\u011Bn\u00ED v\u011Bzen\u00ED.",
              "J: pou\u017E\u00EDt kartu pro opu\u0161t\u011Bn\u00ED v\u011Bzen\u00ED.")
          ]
        when "en"
          [
            rule_section(:aim, "Aim of the game",
              "Buy properties and collect rent when other players land on them. Keep enough money for your own bills, too: the last player who has not gone bankrupt wins.",
              "Two to eight people can play. The default Atlantic City board has forty spaces. Everyone begins on Go with $1,500."),
            rule_section(:turn, "Rolling and moving",
              "At the start of your turn, choose Roll dice and press Enter. The game rolls two dice and moves your piece by their total. What happens next depends on where you land: you might buy a property or pay its owner rent.",
              "Choose actions with the arrows and confirm them with Enter. Once you have dealt with the space, play passes to the next player.",
              "Rolling the same number on both dice is a double. After moving and dealing with the space, you get another roll. A third double in a row sends you straight to jail without making that third move. Going to jail or falling into debt ends your extra rolls.",
              "Press I for everyone's position, Shift+D to browse the board, or C for your cash."),
            rule_section(:buying, "Buying properties",
              "When you land on an unowned property, you can buy it at the stated price. Choose Buy with the arrows and press Enter, or decline if you do not want it. If you cannot afford it, the purchase is skipped. A property that is not bought stays available.",
              "There are three kinds of property:",
              "- Streets belong to colour groups. Owning a whole group raises its rent and lets you build houses.",
              "- Railroads charge more rent when the same owner holds more of them.",
              "- Utilities, such as the electric company and water works, charge rent based on the dice roll. The multiplier depends on how many utilities the owner holds.",
              "Press F for the property card of the space you occupy. It gives the price, rent, building costs and mortgage value. V opens your properties, and Shift+V opens other players' properties. Browse with the arrows and press Enter for details."),
            rule_section(:rent, "Rent",
              "Landing on someone else's property means paying its owner rent. By default, the game collects it automatically. You pay no rent on your own property or on a mortgaged property.",
              "A street's property card lists its rent at each building level. Owning the complete colour group doubles the basic rent on its undeveloped streets. Houses and hotels raise the rent further."),
            rule_section(:events, "Go, taxes and cards",
              "Passing Go pays $200. Landing exactly on Go pays $400.",
              "Some spaces cannot be bought:",
              "- Income Tax costs $200; Luxury Tax costs $100.",
              "- Free Parking pays out its accumulated pot. Taxes and payments to the bank from cards or jail fees go into this pot. After a payout, it starts building up again from zero.",
              "- Chance and Community Chest draw an event card. The game reads and carries out its effect.",
              "An event card may:",
              "- Pay you money from the bank or make you pay.",
              "- Have you pay other players or collect money from each of them.",
              "- Charge for repairs according to the houses and hotels you own.",
              "- Move you to another space. The normal purchase, rent or tax rules apply there unless the card says otherwise.",
              "- Send you to jail.",
              "- Give you a Get Out of Jail Free card to keep for later.",
              "Two movement cards change the rent calculation:",
              "- Going to the nearest railroad doubles its rent.",
              "- Going to the nearest utility makes the rent ten times a fresh roll of two dice.",
              "Buying properties or buildings, mortgaging, and paying other players do not add money to Free Parking."),
            rule_section(:building, "Building houses and hotels",
              "Manage your properties before rolling on your turn. To build on a street:",
              "- You must own every street in its colour group.",
              "- None of the group's streets may be mortgaged.",
              "- You must have enough cash for the building.",
              "Press H to open the available building choices. Select a street with the arrows and press Enter. Each confirmation adds one building at the listed cost.",
              "Build evenly across a colour group. Put one house on every street before adding second houses, and continue that way up to four houses per street. The next building replaces the four houses with a hotel.",
              "The bank has 32 houses and 12 hotels. If it runs out of the buildings you need, wait for some to return. Building a hotel returns the four replaced houses to the bank."),
            rule_section(:selling, "Selling buildings",
              "Press Shift+H, choose a building with the arrows and confirm with Enter to sell it for half its construction cost.",
              "You must sell evenly as well, starting with the most developed streets in the group. Selling a hotel normally replaces it with four houses.",
              "If the bank lacks those four houses, the list offers the sale of all buildings in that colour group. You receive half their construction costs."),
            rule_section(:mortgages, "Mortgages",
              "Mortgaging a property gives you cash from the bank while you keep ownership. Press K, select a property and confirm with Enter. You receive its listed mortgage value, but it stops earning rent.",
              "Before mortgaging a street, sell every building in its colour group.",
              "To lift a mortgage, press Shift+K, choose the property and press Enter. You repay its mortgage value plus ten percent, rounded up to a whole unit. A $100 mortgage therefore costs $110 to repay. The property can then earn rent again."),
            rule_section(:trading, "Trading with another player",
              "You can acquire properties by trading. Before rolling on your own turn, press E, choose another player with the arrows and confirm with Enter.",
              "Enter the cash you offer and the cash you want in return. Tab to each player's property list, browse with the arrows, and use Space to mark the properties to include. A trade can combine several properties and cash.",
              "When ready, Tab to the button for sending the offer and press Enter. The other player presses A to accept or R to reject it. Money and properties change hands only when the offer is accepted.",
              "Trades have these restrictions:",
              "- Mortgaged properties cannot be traded.",
              "- Streets cannot be traded while any buildings remain in their colour group. Sell all buildings in that group first.",
              "- Both players must be able to pay their part. Cash received in the same trade counts towards what they can afford."),
            rule_section(:jail, "Jail",
              "Simply landing on Jail means you are just visiting. You are jailed only when a board space or card sends you there, or you roll three doubles in a row. Being sent to jail ends your turn and does not pay you for Go.",
              "At the start of a turn in jail, choose how to try to leave:",
              "- Press P to pay $50, then roll and move normally.",
              "- Press J to use a Get Out of Jail Free card you hold, then roll normally.",
              "- Roll with Enter and try for a double. You have three consecutive turns to try.",
              "A double rolled in jail frees you and moves you by its total, but does not give an extra roll. If your third attempt is not a double, you pay $50 and move according to that roll.",
              "You still collect rent while in jail and can manage your properties before rolling."),
            rule_section(:debt, "Debt and bankruptcy",
              "If a payment exceeds your cash, you owe a debt. If this happens during your turn, that turn ends. Settle the debt on your next turn before rolling again.",
              "To raise the money, sell buildings, mortgage properties or arrange a trade. Once the full debt is paid, you can roll.",
              "You may give up by pressing B to declare bankruptcy. Bankruptcy happens automatically if, on your turn, you owe money and have no building left to sell or property left to mortgage.",
              "A bankrupt player is eliminated. If they owe another player, that creditor receives their remaining properties and Get Out of Jail Free cards, with buildings settled at half price. If the debt is to the bank, the properties return to the bank."),
            rule_section(:ending, "Winning",
              "The last player who has not gone bankrupt wins. Press S during the game to compare everyone's finances."),
            rule_section(:boards, "Other boards",
              "You can choose another board before play begins. Boards vary in their property names, number of spaces, currency, colour groups, starting cash and Go payment.",
              "Larger boards also have more buildings in the bank. Check each property card for prices, rents and building costs, just as on the standard board.",
              "Some charges are tied to the Go payment:",
              "- Income Tax costs one Go payment.",
              "- Luxury Tax costs half a Go payment.",
              "- Leaving jail costs a quarter of a Go payment.",
              "The rules for colour groups, even building, mortgages and bankruptcy stay the same."),
            rule_section(:auctions, "Auctions",
              "Normally, a declined property stays unowned. You can instead enable auctions before starting. All players still in the game take part in turn, including the person who declined the purchase.",
              "On your auction turn, bid or pass. G places the suggested higher bid. To enter your own amount, press B, type it and confirm with Enter. This is your total bid, not the increase over the previous offer.",
              "Your bid must exceed the current offer and fit within your available cash. To leave the auction, choose the pass action with the arrows and Enter. Once you pass, you cannot rejoin that auction.",
              "When nobody raises the highest bid, its bidder buys the property at that price. If everyone passes without bidding, it stays with the bank.",
              "You can set a time limit for each auction decision. Running out of time counts as passing. Every bidder gets the full time for their decision; zero means no limit."),
            rule_section(:purchase_variant, "Buying after one lap",
              "An optional rule prevents purchases during your first trip around the board. You may buy unowned properties you land on only after you have passed Go for the first time."),
            rule_section(:rent_variants, "Rent options",
              "The table settings offer two changes to rent:",
              "- Turn off automatic rent payments. The owner must press Space to collect rent, or choose to waive it with the arrows and Enter. The game waits for that decision.",
              "- Stop jailed owners from collecting rent. Other players can then land on their properties without paying until the owner is released."),
            rule_section(:event_variants, "Payments and card options",
              "You can also change these rules before starting:",
              "- Disable the Free Parking pot. The space pays nothing, and bank fees are no longer saved there.",
              "- Disable double payment for landing on Go. Landing there then pays the same as passing it.",
              "- Enable lucky snake eyes: rolling two ones earns an extra quarter of the Go payment, or $50 on Atlantic City. This rule is off by default.",
              "- Disable the extra Chance and Community Chest cards. This removes Power Games' additional money events from both decks; the other cards remain in play."),
            rule_section(:controls, "Keyboard shortcuts",
              "Arrow keys: choose an action or property.",
              "Enter: carry out the selected action.",
              "Escape: close the current list.",
              "I: read player positions and space numbers.",
              "T: read whose turn it is and which decision is pending.",
              "C: read your cash.",
              "S: read everyone's finances.",
              "F: read the property card for your current space.",
              "D: browse unowned properties.",
              "Shift+D: browse the whole board.",
              "V: browse your properties.",
              "Shift+V: browse other players' properties.",
              "H: open available building choices.",
              "Shift+H: open buildings available to sell.",
              "K: open properties available to mortgage.",
              "Shift+K: open mortgages you can repay.",
              "E: choose a player and prepare a trade.",
              "A: accept a trade offer.",
              "R: reject a trade offer.",
              "B: declare bankruptcy while settling your debt, or enter a bid during an auction.",
              "G: place the suggested auction bid.",
              "Space: collect rent when manual collection is enabled.",
              "P: pay to leave jail.",
              "J: use a Get Out of Jail Free card.")
          ]
        when "es"
          [
            rule_section(:aim, "Objetivo",
              "En Monopoly compras propiedades y cobras alquiler a quienes caen en ellas. Al mismo tiempo, necesitas efectivo para pagar tus propios gastos. Gana la \u00FAltima persona que no haya quebrado.",
              "Juegan de dos a ocho personas. El tablero habitual es Atlantic City, con cuarenta casillas. Todos empiezan en Salida con 1500 d\u00F3lares."),
            rule_section(:turn, "Dados y movimiento",
              "Al comenzar tu turno, elige lanzar los dados y pulsa Enter. Se lanzan dos dados y tu ficha avanza su suma. La casilla de llegada determina lo que ocurre despu\u00E9s: por ejemplo, comprar una propiedad o pagar alquiler.",
              "Elige las acciones disponibles con las flechas y conf\u00EDrmalas con Enter. Cuando hayas resuelto la casilla y terminado tus acciones, juega la siguiente persona.",
              "Dos dados iguales son dobles y te dan otra tirada despu\u00E9s de resolver la casilla. Pero el tercer doble consecutivo te env\u00EDa a la c\u00E1rcel sin realizar ese tercer movimiento. Ir a la c\u00E1rcel o contraer una deuda pone fin a las tiradas adicionales.",
              "I consulta d\u00F3nde est\u00E1n las fichas, Shift+D permite recorrer el tablero y C lee tu efectivo."),
            rule_section(:buying, "Comprar propiedades",
              "Si caes en una propiedad sin due\u00F1o, puedes comprarla al precio indicado: elige \u00ABComprar\u00BB y pulsa Enter. Si no la quieres, elige \u00ABNo comprar\u00BB. Si no te alcanza el dinero, se omite la compra. Una propiedad no comprada sigue disponible.",
              "Hay tres clases de propiedades:",
              "- Las calles pertenecen a grupos de colores. Completar un grupo permite cobrar m\u00E1s y construir casas.",
              "- Las estaciones cobran m\u00E1s alquiler cuantas m\u00E1s tenga el mismo propietario.",
              "- Los servicios, como la compa\u00F1\u00EDa el\u00E9ctrica y la de aguas, calculan el alquiler a partir de los dados. El multiplicador depende de cu\u00E1ntos servicios posea el due\u00F1o.",
              "F lee la tarjeta de la propiedad donde est\u00E1s, con precio, alquiler y costes de construcci\u00F3n o hipoteca. V abre tus propiedades y Shift+V las ajenas. Elige una con las flechas y pulsa Enter para consultar sus detalles."),
            rule_section(:rent, "Alquileres",
              "Al caer en una propiedad ajena pagas alquiler a su due\u00F1o. Por defecto se cobra autom\u00E1ticamente. No pagas por tus propias casillas ni por propiedades hipotecadas.",
              "En las calles, la tarjeta indica el alquiler seg\u00FAn sus edificios. Si el propietario tiene todo el grupo de color, una calle de ese grupo sin edificios cobra el doble de su alquiler b\u00E1sico. Las casas y hoteles aplican las tarifas superiores de la tarjeta."),
            rule_section(:events, "Salida, impuestos y cartas",
              "Pasar por Salida da 200 d\u00F3lares. Si terminas exactamente en ella, recibes 400.",
              "Adem\u00E1s de propiedades hay casillas que no se compran:",
              "- El impuesto sobre la renta cuesta 200 d\u00F3lares y el de lujo, 100.",
              "- Aparcamiento gratuito entrega el fondo acumulado. Lo alimentan los impuestos y los pagos al banco por cartas o por salir de la c\u00E1rcel. Tras cobrarlo, vuelve a empezar desde cero.",
              "- Suerte y Caja de Comunidad sacan una carta de evento. Se anuncia y se aplica inmediatamente.",
              "Seg\u00FAn la carta, puede ocurrir lo siguiente:",
              "- Recibes dinero del banco o debes pagarle.",
              "- Pagas a los otros jugadores o cobras una cantidad de cada uno.",
              "- Pagas reparaciones seg\u00FAn las casas y hoteles que tengas.",
              "- Tu ficha se traslada a otra casilla, donde se aplican las compras, alquileres o impuestos normales, salvo que la carta indique otra cosa.",
              "- Vas a la c\u00E1rcel.",
              "- Recibes una carta para salir de la c\u00E1rcel que puedes guardar hasta usarla.",
              "Dos desplazamientos por carta cambian el alquiler:",
              "- Ir a la estaci\u00F3n m\u00E1s cercana obliga a pagar el doble del alquiler correspondiente.",
              "- Ir al servicio m\u00E1s cercano obliga a pagar diez veces el resultado de una nueva tirada de dos dados.",
              "Las compras de propiedades y edificios, las hipotecas y los pagos entre jugadores no a\u00F1aden dinero al fondo de aparcamiento gratuito."),
            rule_section(:building, "Construir casas y hoteles",
              "Administras tus propiedades en tu turno, antes de lanzar. Solo se construye en calles, y deben cumplirse estas condiciones:",
              "- Tienes todas las calles del grupo de color.",
              "- Ninguna calle del grupo est\u00E1 hipotecada.",
              "- Puedes pagar la construcci\u00F3n.",
              "Pulsa H para abrir las construcciones posibles. Elige una calle con las flechas y confirma con Enter. Cada confirmaci\u00F3n a\u00F1ade un edificio al precio indicado.",
              "Debes construir de manera uniforme: pon una casa en cada calle antes de empezar la segunda, y sigue igual hasta llegar a cuatro por calle. La siguiente construcci\u00F3n sustituye las cuatro casas por un hotel.",
              "El banco dispone de treinta y dos casas y doce hoteles. Si se agotan los que necesitas, hay que esperar a que vuelvan al banco. Al construir un hotel, las cuatro casas sustituidas regresan a la reserva."),
            rule_section(:selling, "Vender edificios",
              "Para recuperar efectivo, pulsa Shift+H, elige el edificio con las flechas y confirma con Enter. Recibes la mitad de su coste de construcci\u00F3n.",
              "Tambi\u00E9n debes vender de manera uniforme, empezando por las calles m\u00E1s edificadas del grupo. Normalmente, al vender un hotel vuelve a haber cuatro casas en esa calle.",
              "Si el banco no tiene las cuatro casas necesarias, puedes elegir vender todos los edificios de ese color. Recibes la mitad de sus costes de construcci\u00F3n."),
            rule_section(:mortgages, "Hipotecas",
              "Una hipoteca te da dinero del banco sin perder la propiedad. Pulsa K, elige la propiedad y confirma con Enter. Recibes el importe de hipoteca de su tarjeta, pero deja de generar alquiler.",
              "Antes de hipotecar una calle debes vender todos los edificios de su grupo de color.",
              "Para levantar una hipoteca, pulsa Shift+K, elige la propiedad y confirma. Pagas el importe hipotecado m\u00E1s un diez por ciento, redondeado hacia arriba a una unidad entera. Por ejemplo, una hipoteca de 100 se levanta por 110. La propiedad vuelve a cobrar alquiler."),
            rule_section(:trading, "Intercambios",
              "Puedes conseguir propiedades negociando con otro jugador. Antes de tirar en tu turno, pulsa E, elige a la otra persona con las flechas y confirma con Enter.",
              "Escribe cu\u00E1nto dinero ofreces y cu\u00E1nto pides. Con Tab pasa a las listas de propiedades de ambos: rec\u00F3rrelas con las flechas y marca con Espacio las incluidas en el acuerdo. Puedes combinar varias propiedades y dinero.",
              "Cuando est\u00E9 listo, ve con Tab al bot\u00F3n para enviar la propuesta y pulsa Enter. El destinatario la acepta con A o la rechaza con R. El dinero y las propiedades solo cambian de manos si la acepta.",
              "Se aplican estas restricciones:",
              "- No puedes intercambiar propiedades hipotecadas.",
              "- No puedes intercambiar una calle mientras quede alg\u00FAn edificio en su grupo. Primero debes vender toda la construcci\u00F3n de ese color.",
              "- Ambas partes deben poder pagar su aportaci\u00F3n. Tambi\u00E9n se cuenta el dinero que recibir\u00E1n en el mismo intercambio."),
            rule_section(:jail, "La c\u00E1rcel",
              "Caer normalmente en la casilla de c\u00E1rcel es solo una visita. Quedas encarcelado si te env\u00EDa all\u00ED una casilla, una carta o tu tercer doble consecutivo. El traslado termina el turno y no da dinero por Salida.",
              "Al empezar un turno encarcelado tienes tres opciones:",
              "- Pulsa P para pagar 50 d\u00F3lares; despu\u00E9s tiras y avanzas normalmente.",
              "- Si tienes una carta para salir, \u00FAsala con J; despu\u00E9s haces una tirada normal.",
              "- Pulsa Enter para intentar sacar dobles. Tienes tres turnos consecutivos para conseguirlo.",
              "Un doble te libera y avanzas su suma, pero no te da otra tirada. Si el tercer intento tampoco da dobles, pagas 50 d\u00F3lares y avanzas el resultado de esa \u00FAltima tirada.",
              "En la c\u00E1rcel sigues cobrando alquileres y puedes administrar tus bienes antes de tirar."),
            rule_section(:debt, "Deudas y bancarrota",
              "Si debes pagar m\u00E1s efectivo del que tienes, contraes una deuda. Si ocurre durante tu movimiento, termina tu turno. Tendr\u00E1s que pagarla en tu siguiente turno antes de volver a tirar.",
              "Puedes vender edificios, hipotecar propiedades o conseguir dinero mediante un intercambio. Una vez saldada toda la deuda, puedes volver a lanzar los dados.",
              "Tambi\u00E9n puedes abandonar declarando la bancarrota con B. La bancarrota es autom\u00E1tica si tienes una deuda en tu turno y ya no puedes vender ning\u00FAn edificio ni hipotecar ninguna propiedad.",
              "Quien quiebra queda eliminado. Si la deuda era con otro jugador, ese acreedor recibe las propiedades restantes y las cartas para salir de la c\u00E1rcel; los edificios se liquidan a mitad de precio. Si se deb\u00EDa al banco, las propiedades regresan al banco."),
            rule_section(:ending, "Final de partida",
              "Gana el \u00FAltimo jugador que no haya quebrado. S permite comparar las finanzas de los jugadores durante la partida."),
            rule_section(:boards, "Otros tableros",
              "Puedes elegir otro tablero antes de jugar. Cambian los nombres y la cantidad de casillas, la moneda, los grupos de propiedades, el efectivo inicial y el pago por pasar por Salida.",
              "Los tableros mayores tambi\u00E9n tienen m\u00E1s edificios en el banco. Consulta precios, alquileres y costes de construcci\u00F3n en las tarjetas de propiedad, igual que en el tablero habitual.",
              "Algunos pagos se calculan a partir del ingreso de Salida:",
              "- El impuesto sobre la renta equivale a un ingreso de Salida.",
              "- El impuesto de lujo equivale a la mitad.",
              "- Salir de la c\u00E1rcel cuesta la cuarta parte.",
              "Se conservan las reglas de grupos de color, construcci\u00F3n uniforme, hipotecas y bancarrota."),
            rule_section(:auctions, "Subastas",
              "Normalmente una propiedad no comprada queda libre. Puedes activar su subasta antes de jugar. Participan por turnos todos los jugadores que sigan en la partida, incluido quien rechaz\u00F3 comprarla.",
              "Cuando te toque, puedes subir o pasar. G presenta la oferta superior sugerida. Con B puedes escribir tu propia cantidad y confirmarla con Enter: es la oferta total, no lo que a\u00F1ades a la anterior.",
              "La oferta debe superar la actual y no exceder tu efectivo. Para pasar, elige retirarte de la subasta con las flechas y confirma con Enter. No puedes volver a entrar en esa misma subasta.",
              "Cuando nadie supera la oferta m\u00E1s alta, su autor compra al precio ofrecido. Si todos pasan sin ofertar, la propiedad sigue en el banco.",
              "Puedes fijar un plazo para cada decisi\u00F3n. No responder a tiempo equivale a pasar. Cada nuevo postor recibe el plazo completo; cero significa tiempo ilimitado."),
            rule_section(:purchase_variant, "Comprar tras la primera vuelta",
              "Puedes prohibir las compras durante la primera vuelta. En ese caso solo podr\u00E1s comprar propiedades libres al caer en ellas despu\u00E9s de haber pasado por Salida por primera vez."),
            rule_section(:rent_variants, "Variantes del alquiler",
              "Hay dos ajustes relativos a los alquileres:",
              "- Sin pagos autom\u00E1ticos, el propietario debe reclamar el alquiler con Espacio o renunciar a \u00E9l eligiendo esa opci\u00F3n y confirmando con Enter. La partida espera su decisi\u00F3n.",
              "- Puedes impedir que los encarcelados cobren alquiler. Sus propiedades se visitan gratis mientras sigan presos."),
            rule_section(:event_variants, "Variantes de pagos y cartas",
              "Antes de empezar tambi\u00E9n puedes cambiar estas reglas:",
              "- Sin fondo de aparcamiento gratuito, la casilla no paga nada y no se reservan los pagos al banco.",
              "- Sin pago doble por llegar a Salida, caer exactamente en ella da lo mismo que pasar.",
              "- La suerte del doble uno da una bonificaci\u00F3n al sacar dos unos: la cuarta parte del pago de Salida, o 50 d\u00F3lares en Atlantic City. Est\u00E1 desactivada por defecto.",
              "- Puedes retirar las cartas adicionales de Suerte y Caja de Comunidad. Desaparecen los eventos de dinero a\u00F1adidos por Power Games; las dem\u00E1s cartas siguen en juego."),
            rule_section(:controls, "Teclas de referencia",
              "Flechas: elegir una acci\u00F3n o propiedad.",
              "Enter: realizar la acci\u00F3n elegida.",
              "Escape: cerrar la lista actual.",
              "I: consultar las posiciones y n\u00FAmeros de casilla de los jugadores.",
              "T: consultar de qui\u00E9n es el turno y qu\u00E9 decisi\u00F3n falta.",
              "C: consultar tu efectivo.",
              "S: consultar las finanzas de todos.",
              "F: leer la tarjeta de la propiedad donde est\u00E1s.",
              "D: revisar las propiedades sin due\u00F1o.",
              "Shift+D: recorrer todo el tablero.",
              "V: revisar tus propiedades.",
              "Shift+V: revisar las propiedades ajenas.",
              "H: abrir las propiedades donde puedes construir.",
              "Shift+H: abrir los edificios que puedes vender.",
              "K: abrir las propiedades que puedes hipotecar.",
              "Shift+K: abrir las hipotecas que puedes levantar.",
              "E: elegir jugador y preparar un intercambio.",
              "A: aceptar una propuesta de intercambio.",
              "R: rechazar una propuesta de intercambio.",
              "B: declarar la bancarrota al resolver tu deuda o escribir una oferta durante una subasta.",
              "G: presentar la oferta sugerida en una subasta.",
              "Espacio: reclamar alquiler si el cobro es manual.",
              "P: pagar para salir de la c\u00E1rcel.",
              "J: usar tu carta para salir de la c\u00E1rcel.")
          ]
        when "pl"
          [
            rule_section(:aim, "Cel gry",
              "W Monopoly kupujesz nieruchomo\u015Bci i pobierasz czynsz od graczy, kt\u00F3rzy na nich stan\u0105. Musisz jednocze\u015Bnie zachowa\u0107 pieni\u0105dze na w\u0142asne op\u0142aty. Wygrywa ostatnia osoba, kt\u00F3ra nie zbankrutuje.",
              "Gra jest dla dw\u00F3ch do o\u015Bmiu os\u00F3b. Przy zwyk\u0142ych ustawieniach u\u017Cywa si\u0119 planszy Atlantic City z czterdziestoma polami. Wszyscy zaczynaj\u0105 na Starcie i maj\u0105 po 1500 dolar\u00F3w."),
            rule_section(:turn, "Rzut ko\u015B\u0107mi i ruch",
              "Na pocz\u0105tku swojej kolejki wybierz \u201ERzu\u0107 ko\u015B\u0107mi\u201D i naci\u015Bnij Enter. Gra rzuci dwiema ko\u015B\u0107mi i przesunie tw\u00F3j pionek o sum\u0119 oczek. Dalszy przebieg tury zale\u017Cy od pola, na kt\u00F3rym staniesz: mo\u017Cesz na przyk\u0142ad kupi\u0107 nieruchomo\u015B\u0107 albo zap\u0142aci\u0107 czynsz jej w\u0142a\u015Bcicielowi.",
              "Dost\u0119pne czynno\u015Bci wybierasz strza\u0142kami i zatwierdzasz Enterem. Gdy zako\u0144czysz wszystkie czynno\u015Bci na danym polu, tur\u0119 rozpoczyna nast\u0119pny gracz.",
              "Dwie jednakowe liczby na ko\u015Bciach to dublet. Po wykonaniu ruchu i rozliczeniu pola dostajesz za niego kolejny rzut. Trzeci dublet z rz\u0119du wysy\u0142a Ci\u0119 jednak do wi\u0119zienia, bez wykonywania trzeciego ruchu. Trafienie do wi\u0119zienia lub powstanie d\u0142ugu ko\u0144czy dodatkowe rzuty.",
              "Klawisz I odczytuje, gdzie stoj\u0105 gracze. Shift+D pozwala przejrze\u0107 plansz\u0119, a C sprawdzi\u0107 w\u0142asn\u0105 got\u00F3wk\u0119."),
            rule_section(:buying, "Kupowanie nieruchomo\u015Bci",
              "Je\u015Bli staniesz na nieruchomo\u015Bci bez w\u0142a\u015Bciciela, mo\u017Cesz kupi\u0107 j\u0105 za podan\u0105 cen\u0119. Wybierz strza\u0142kami \u201EKup\u201D i naci\u015Bnij Enter. Je\u015Bli nie chcesz kupowa\u0107, wybierz \u201ENie kupuj\u201D. Gdy nie masz do\u015B\u0107 pieni\u0119dzy, zakup zostaje pomini\u0119ty. Niekupiona nieruchomo\u015B\u0107 pozostaje wolna.",
              "Nieruchomo\u015Bci dziel\u0105 si\u0119 na trzy rodzaje:",
              "- Ulice nale\u017C\u0105 do grup oznaczonych kolorami. Zebranie ca\u0142ej grupy pozwala pobiera\u0107 wi\u0119kszy czynsz i budowa\u0107 na niej domy.",
              "- Dworce przynosz\u0105 tym wy\u017Cszy czynsz, im wi\u0119cej dworc\u00F3w ma ten sam w\u0142a\u015Bciciel.",
              "- Zak\u0142ady, takie jak elektrownia i wodoci\u0105gi, naliczaj\u0105 czynsz wed\u0142ug wyniku rzutu ko\u015B\u0107mi. Mno\u017Cnik zale\u017Cy od tego, ile zak\u0142ad\u00F3w ma w\u0142a\u015Bciciel.",
              "Klawisz F odczytuje kart\u0119 nieruchomo\u015Bci, na kt\u00F3rej stoisz. Znajdziesz tam cen\u0119, czynsz i koszty zwi\u0105zane z zabudow\u0105 lub zastawem. Swoje nieruchomo\u015Bci przegl\u0105dasz klawiszem V, a cudze przez Shift+V. Na li\u015Bcie wybierz pozycj\u0119 strza\u0142kami i naci\u015Bnij Enter, by pozna\u0107 szczeg\u00F3\u0142y."),
            rule_section(:rent, "P\u0142acenie czynszu",
              "Po wej\u015Bciu na cudz\u0105 nieruchomo\u015B\u0107 p\u0142acisz jej w\u0142a\u015Bcicielowi czynsz. Przy zwyk\u0142ych ustawieniach gra pobiera go sama. Nie p\u0142acisz za w\u0142asne pole ani za nieruchomo\u015B\u0107, kt\u00F3ra jest zastawiona.",
              "Czynsz za ulic\u0119 wynika z jej karty i liczby budynk\u00F3w. Je\u015Bli w\u0142a\u015Bciciel zebra\u0142 ca\u0142y kolor, ale na danej ulicy nie ma jeszcze budynk\u00F3w, podstawowy czynsz za t\u0119 ulic\u0119 jest podwojony. Domy i hotele pozwalaj\u0105 pobiera\u0107 kolejne, wy\u017Csze stawki."),
            rule_section(:events, "Start, podatki i karty",
              "Za przej\u015Bcie przez Start otrzymujesz 200 dolar\u00F3w. Je\u015Bli sko\u0144czysz ruch dok\u0142adnie na Starcie, dostajesz 400 dolar\u00F3w.",
              "Na planszy spotkasz tak\u017Ce pola, kt\u00F3rych nie kupujesz:",
              "- Podatek dochodowy kosztuje 200 dolar\u00F3w, a podatek od luksusu 100.",
              "- Bezp\u0142atny parking wyp\u0142aca ca\u0142\u0105 zgromadzon\u0105 pul\u0119. Trafiaj\u0105 do niej podatki i op\u0142aty dla banku z kart lub za wyj\u015Bcie z wi\u0119zienia. Po wyp\u0142acie pula zaczyna zbiera\u0107 si\u0119 od zera.",
              "- Szansa i Kasa Spo\u0142eczna uruchamiaj\u0105 kart\u0119 zdarzenia. Gra odczytuje jej dzia\u0142anie i od razu je wykonuje.",
              "Dzia\u0142anie kart zale\u017Cy od tego, kt\u00F3ra zostanie dobrana:",
              "- Karta mo\u017Ce da\u0107 Ci pieni\u0105dze z banku albo nakaza\u0107 zap\u0142at\u0119.",
              "- Niekt\u00F3re karty ka\u017C\u0105 wp\u0142aca\u0107 pieni\u0105dze innym graczom lub odebra\u0107 nale\u017Cno\u015B\u0107 od ka\u017Cdego z nich.",
              "- Karty remont\u00F3w naliczaj\u0105 op\u0142at\u0119 zale\u017Cn\u0105 od posiadanych dom\u00F3w i hoteli.",
              "- Karta mo\u017Ce przenie\u015B\u0107 tw\u00F3j pionek na inne pole. Obowi\u0105zuj\u0105 tam zwyk\u0142e zasady zakupu nieruchomo\u015Bci, p\u0142acenia czynszu czy podatku, chyba \u017Ce karta m\u00F3wi inaczej.",
              "- Mo\u017Cesz trafi\u0107 na kart\u0119 wysy\u0142aj\u0105c\u0105 do wi\u0119zienia.",
              "- Kart\u0119 wyj\u015Bcia z wi\u0119zienia zachowujesz do p\u00F3\u017Aniejszego u\u017Cycia.",
              "Niekt\u00F3re karty przenosz\u0105ce pionek zmieniaj\u0105 spos\u00F3b naliczania czynszu:",
              "- Karta prowadz\u0105ca do najbli\u017Cszego dworca podwaja nale\u017Cny za niego czynsz.",
              "- Przy przeniesieniu do najbli\u017Cszego zak\u0142adu nale\u017Cny czynsz wynosi dziesi\u0119ciokrotno\u015B\u0107 nowego rzutu dwiema ko\u015B\u0107mi.",
              "Zakupy nieruchomo\u015Bci i budynk\u00F3w, zastawy oraz p\u0142atno\u015Bci mi\u0119dzy graczami nie zasilaj\u0105 puli bezp\u0142atnego parkingu."),
            rule_section(:building, "Budowanie dom\u00F3w i hoteli",
              "Nieruchomo\u015Bciami zarz\u0105dzasz w swojej turze przed rzutem. Budowa\u0107 mo\u017Cna tylko na ulicach, po spe\u0142nieniu nast\u0119puj\u0105cych warunk\u00F3w:",
              "- Musisz mie\u0107 wszystkie ulice nale\u017C\u0105ce do danego koloru.",
              "- \u017Badna ulica w tej grupie nie mo\u017Ce by\u0107 zastawiona.",
              "- Musisz mie\u0107 pieni\u0105dze na op\u0142acenie budowy.",
              "Naci\u015Bnij H, \u017Ceby otworzy\u0107 list\u0119 mo\u017Cliwych bud\u00F3w. Wybierz ulic\u0119 strza\u0142kami i zatwierd\u017A Enterem. Ka\u017Cde zatwierdzenie dodaje jeden budynek za cen\u0119 podan\u0105 na li\u015Bcie.",
              "Domy buduje si\u0119 r\u00F3wnomiernie w ca\u0142ej grupie. Najpierw postaw po jednym na ka\u017Cdej ulicy, zanim zaczniesz dodawa\u0107 drugie. W ten sam spos\u00F3b dochodzisz do czterech dom\u00F3w na ulicy. Nast\u0119pna budowa zamienia te cztery domy w hotel.",
              "Bank ma trzydzie\u015Bci dwa domy i dwana\u015Bcie hoteli. Gdy zabraknie potrzebnych budynk\u00F3w, trzeba poczeka\u0107, a\u017C wr\u00F3c\u0105 do banku. Przy stawianiu hotelu cztery zast\u0105pione domy wracaj\u0105 do zapasu."),
            rule_section(:selling, "Sprzedawanie budynk\u00F3w",
              "Aby odzyska\u0107 cz\u0119\u015B\u0107 pieni\u0119dzy, naci\u015Bnij Shift+H. Na li\u015Bcie wybierz strza\u0142kami budynek do sprzedania i zatwierd\u017A Enterem. Otrzymasz po\u0142ow\u0119 jego ceny budowy.",
              "Sprzeda\u017C r\u00F3wnie\u017C musi by\u0107 r\u00F3wnomierna: zaczynasz od ulic, kt\u00F3re maj\u0105 najwi\u0119cej budynk\u00F3w w grupie. Sprzedany hotel zwykle zamienia si\u0119 z powrotem w cztery domy.",
              "Je\u015Bli bank nie ma czterech dom\u00F3w potrzebnych do zast\u0105pienia hotelu, mo\u017Cesz wybra\u0107 z listy sprzeda\u017C wszystkich budynk\u00F3w w tym kolorze. Otrzymasz po\u0142ow\u0119 koszt\u00F3w ich budowy."),
            rule_section(:mortgages, "Zastawianie nieruchomo\u015Bci",
              "Zastaw pozwala dosta\u0107 pieni\u0105dze z banku bez oddawania w\u0142asno\u015Bci. Naci\u015Bnij K, wybierz nieruchomo\u015B\u0107 strza\u0142kami i zatwierd\u017A Enterem. Dostaniesz kwot\u0119 zastawu z jej karty, ale przestaniesz pobiera\u0107 z niej czynsz.",
              "Zanim zastawisz ulic\u0119, musisz sprzeda\u0107 wszystkie budynki w ca\u0142ej jej grupie kolorystycznej.",
              "Aby wykupi\u0107 zastaw, naci\u015Bnij Shift+K, wybierz nieruchomo\u015B\u0107 i zatwierd\u017A Enterem. P\u0142acisz kwot\u0119 zastawu powi\u0119kszon\u0105 o dziesi\u0119\u0107 procent, z zaokr\u0105gleniem w g\u00F3r\u0119 do pe\u0142nej jednostki. Na przyk\u0142ad zastaw za 100 wykupujesz za 110. Potem nieruchomo\u015B\u0107 zn\u00F3w przynosi czynsz."),
            rule_section(:trading, "Wymiana z innym graczem",
              "Nieruchomo\u015Bci mo\u017Cesz te\u017C zdobywa\u0107 przez wymian\u0119. We w\u0142asnej turze przed rzutem naci\u015Bnij E, wybierz drugiego gracza strza\u0142kami i zatwierd\u017A Enterem.",
              "W propozycji wpisujesz, ile pieni\u0119dzy dajesz i ile chcesz otrzyma\u0107. Tabem przechodzisz do list nieruchomo\u015Bci obu stron. Na ka\u017Cdej li\u015Bcie wybierasz pozycje strza\u0142kami, a Spacj\u0105 zaznaczasz te, kt\u00F3re maj\u0105 wej\u015B\u0107 do wymiany. Mo\u017Cesz po\u0142\u0105czy\u0107 kilka nieruchomo\u015Bci z dop\u0142at\u0105.",
              "Gdy oferta jest gotowa, przejd\u017A Tabem do \u201EWy\u015Blij propozycj\u0119\u201D i naci\u015Bnij Enter. Druga osoba przyjmuje j\u0105 klawiszem A albo odrzuca klawiszem R. Dopiero przyj\u0119cie oferty przenosi pieni\u0105dze i nieruchomo\u015Bci.",
              "Wymiana ma nast\u0119puj\u0105ce ograniczenia:",
              "- Nie mo\u017Cna przekazywa\u0107 zastawionych nieruchomo\u015Bci.",
              "- Nie mo\u017Cna przekazywa\u0107 ulic z grupy, na kt\u00F3rej stoj\u0105 jeszcze jakiekolwiek budynki. Najpierw trzeba sprzeda\u0107 zabudow\u0119 ca\u0142ego koloru.",
              "- Obie strony musz\u0105 m\u00F3c op\u0142aci\u0107 swoj\u0105 cz\u0119\u015B\u0107. Gra uwzgl\u0119dnia tak\u017Ce pieni\u0105dze otrzymywane w tej samej wymianie."),
            rule_section(:jail, "Wi\u0119zienie",
              "Zatrzymanie si\u0119 na polu wi\u0119zienia to tylko odwiedziny. Odbywasz kar\u0119 dopiero wtedy, gdy skieruje ci\u0119 tam pole planszy lub karta albo wyrzucisz trzy dublety z rz\u0119du. Wys\u0142anie do wi\u0119zienia ko\u0144czy tur\u0119 i nie daje wyp\u0142aty za Start.",
              "Na pocz\u0105tku tury w wi\u0119zieniu mo\u017Cesz wybra\u0107 jeden z trzech sposob\u00F3w wyj\u015Bcia:",
              "- Naci\u015Bnij P, aby zap\u0142aci\u0107 50 dolar\u00F3w. Potem rzucasz ko\u015B\u0107mi i ruszasz normalnie.",
              "- Je\u015Bli masz kart\u0119 wyj\u015Bcia z wi\u0119zienia, naci\u015Bnij J, aby j\u0105 wykorzysta\u0107. Potem r\u00F3wnie\u017C wykonujesz zwyk\u0142y rzut.",
              "- Mo\u017Cesz od razu rzuci\u0107 Enterem i spr\u00F3bowa\u0107 uzyska\u0107 dublet. Masz na to trzy kolejne tury.",
              "Dublet wyrzucony w wi\u0119zieniu uwalnia Ci\u0119 i pozwala przesun\u0105\u0107 pionek o jego sum\u0119, ale nie daje dodatkowego rzutu. Je\u015Bli trzecia pr\u00F3ba te\u017C nie przyniesie dubletu, p\u0142acisz 50 dolar\u00F3w i wykonujesz ruch zgodnie z tym ostatnim rzutem.",
              "Podczas pobytu w wi\u0119zieniu nadal pobierasz czynsz i mo\u017Cesz zarz\u0105dza\u0107 swoim maj\u0105tkiem przed rzutem."),
            rule_section(:debt, "D\u0142ug i bankructwo",
              "Je\u015Bli nale\u017Cno\u015B\u0107 jest wi\u0119ksza ni\u017C Twoja got\u00F3wka, powstaje d\u0142ug. Gdy zdarzy si\u0119 to podczas Twojego ruchu, Twoja tura si\u0119 ko\u0144czy. D\u0142ug sp\u0142acasz we w\u0142asnej nast\u0119pnej turze, zanim zn\u00F3w rzucisz ko\u015B\u0107mi.",
              "\u017Beby sp\u0142aci\u0107 d\u0142ug, mo\u017Cesz sprzedawa\u0107 budynki, zastawia\u0107 nieruchomo\u015Bci lub zdoby\u0107 pieni\u0105dze przez wymian\u0119. Gdy sp\u0142acisz ca\u0142\u0105 nale\u017Cno\u015B\u0107, mo\u017Cesz zn\u00F3w rzuci\u0107 ko\u015B\u0107mi.",
              "Mo\u017Cesz te\u017C zrezygnowa\u0107 z dalszej gry, naciskaj\u0105c B, \u017Ceby og\u0142osi\u0107 bankructwo. Bankrutujesz automatycznie, gdy w swojej turze masz d\u0142ug, a nie mo\u017Cesz ju\u017C sprzeda\u0107 \u017Cadnego budynku ani zastawi\u0107 nieruchomo\u015Bci.",
              "Bankrut odpada. Je\u015Bli jest winien pieni\u0105dze innemu graczowi, ten otrzymuje jego pozosta\u0142e nieruchomo\u015Bci i karty wyj\u015Bcia z wi\u0119zienia, a budynki s\u0105 rozliczane za po\u0142ow\u0119 ceny. Przy d\u0142ugu wobec banku nieruchomo\u015Bci wracaj\u0105 do banku."),
            rule_section(:ending, "Koniec gry",
              "Wygrywa ostatni gracz, kt\u00F3ry nie zbankrutowa\u0142. Klawisz S pozwala podczas gry por\u00F3wna\u0107 finanse graczy."),
            rule_section(:boards, "Inne plansze",
              "Przed gr\u0105 mo\u017Cna wybra\u0107 inn\u0105 plansz\u0119 ni\u017C Atlantic City. Plansze r\u00F3\u017Cni\u0105 si\u0119 nazwami i liczb\u0105 p\u00F3l, walut\u0105, grupami nieruchomo\u015Bci, pocz\u0105tkow\u0105 got\u00F3wk\u0105 oraz wyp\u0142at\u0105 za Start.",
              "Na wi\u0119kszych planszach jest te\u017C wi\u0119cej budynk\u00F3w w banku. Ceny, czynsze i koszty zabudowy odczytuj z kart nieruchomo\u015Bci, tak samo jak w zwyk\u0142ej grze.",
              "Niekt\u00F3re op\u0142aty s\u0105 powi\u0105zane z wyp\u0142at\u0105 za Start:",
              "- Podatek dochodowy kosztuje jedn\u0105 tak\u0105 wyp\u0142at\u0119.",
              "- Podatek od luksusu kosztuje po\u0142ow\u0119 wyp\u0142aty.",
              "- Wyj\u015Bcie z wi\u0119zienia kosztuje jedn\u0105 czwart\u0105 wyp\u0142aty.",
              "Zasady zbierania kolor\u00F3w, r\u00F3wnomiernej zabudowy, zastaw\u00F3w i bankructwa pozostaj\u0105 takie same."),
            rule_section(:auctions, "Aukcje",
              "Zwykle nieruchomo\u015B\u0107, kt\u00F3rej gracz nie kupi\u0142, pozostaje wolna. Przed gr\u0105 mo\u017Cna w\u0142\u0105czy\u0107 aukcje takich nieruchomo\u015Bci. W licytacji uczestnicz\u0105 kolejno wszyscy pozostali w grze, tak\u017Ce osoba, kt\u00F3ra wcze\u015Bniej odm\u00F3wi\u0142a zakupu.",
              "Gdy nadejdzie Twoja kolej, mo\u017Cesz przebi\u0107 ofert\u0119 albo spasowa\u0107. Klawisz G sk\u0142ada podpowiadan\u0105 wy\u017Csz\u0105 ofert\u0119. Je\u015Bli chcesz zaproponowa\u0107 w\u0142asn\u0105 kwot\u0119, naci\u015Bnij B, wpisz j\u0105 i zatwierd\u017A Enterem. Jest to ca\u0142a kwota, kt\u00F3r\u0105 oferujesz, nie sama dop\u0142ata do poprzedniej oferty.",
              "Twoja oferta musi by\u0107 wy\u017Csza od obecnej i mie\u015Bci\u0107 si\u0119 w dost\u0119pnej got\u00F3wce. Aby wycofa\u0107 si\u0119 z tej aukcji, wybierz strza\u0142kami \u201EWycofaj si\u0119 z aukcji\u201D i zatwierd\u017A Enterem. Po spasowaniu nie wracasz do tej samej licytacji.",
              "Gdy nikt ju\u017C nie przebije najwy\u017Cszej oferty, jej autor kupuje nieruchomo\u015B\u0107 za zaoferowan\u0105 cen\u0119. Je\u015Bli wszyscy spasuj\u0105 bez \u017Cadnej oferty, nieruchomo\u015B\u0107 pozostaje w banku.",
              "Dla aukcji mo\u017Cna ustawi\u0107 liczb\u0119 sekund na ka\u017Cd\u0105 decyzj\u0119. Brak odpowiedzi w tym czasie oznacza pas. Ka\u017Cdy nast\u0119pny licytuj\u0105cy dostaje w\u0142asny pe\u0142ny czas; warto\u015B\u0107 zero oznacza brak ograniczenia."),
            rule_section(:purchase_variant, "Zakupy dopiero po okr\u0105\u017Ceniu",
              "Mo\u017Cna zabroni\u0107 kupowania w pierwszym okr\u0105\u017Ceniu planszy. Wtedy dopiero po swoim pierwszym przej\u015Bciu przez Start mo\u017Cesz kupowa\u0107 wolne nieruchomo\u015Bci, na kt\u00F3rych staniesz."),
            rule_section(:rent_variants, "Zmiany pobierania czynszu",
              "W ustawieniach przed gr\u0105 mo\u017Cna zmieni\u0107 dwie zasady zwi\u0105zane z czynszem:",
              "- Po wy\u0142\u0105czeniu automatycznych p\u0142atno\u015Bci o czynsz musi upomnie\u0107 si\u0119 w\u0142a\u015Bciciel nieruchomo\u015Bci. Naciska Spacj\u0119, by go pobra\u0107, albo wybiera strza\u0142kami rezygnacj\u0119 z czynszu i zatwierdza Enterem. Gra czeka na t\u0119 decyzj\u0119.",
              "- Mo\u017Cna wy\u0142\u0105czy\u0107 pobieranie czynszu przez osoby siedz\u0105ce w wi\u0119zieniu. Wtedy inni gracze odwiedzaj\u0105 ich nieruchomo\u015Bci bez tej op\u0142aty a\u017C do uwolnienia w\u0142a\u015Bciciela."),
            rule_section(:event_variants, "Zmiany wyp\u0142at i kart",
              "Przed gr\u0105 mo\u017Cna te\u017C zmieni\u0107 nast\u0119puj\u0105ce zasady:",
              "- Wy\u0142\u0105czenie puli bezp\u0142atnego parkingu sprawia, \u017Ce to pole nic nie wyp\u0142aca, a op\u0142aty przeznaczone dla banku nie s\u0105 odk\u0142adane do puli.",
              "- Po wy\u0142\u0105czeniu podw\u00F3jnej wyp\u0142aty dok\u0142adne zatrzymanie na Starcie daje tyle samo pieni\u0119dzy, co zwyk\u0142e przej\u015Bcie przez niego.",
              "- Szcz\u0119\u015Bliwa podw\u00F3jna jedynka daje dodatkow\u0105 premi\u0119 za wyrzucenie dw\u00F3ch jedynek. Wynosi ona jedn\u0105 czwart\u0105 wyp\u0142aty za Start, czyli 50 dolar\u00F3w na planszy Atlantic City. Ta zasada jest zwykle wy\u0142\u0105czona.",
              "- Mo\u017Cna wy\u0142\u0105czy\u0107 dodatkowe karty Szansy i Kasy Spo\u0142ecznej. Z obu talii znikaj\u0105 wtedy dodatkowe zdarzenia pieni\u0119\u017Cne Power Games; pozosta\u0142e karty nadal dzia\u0142aj\u0105."),
            rule_section(:controls, "Skr\u00F3ty klawiszowe",
              "Strza\u0142ki: wybierz czynno\u015B\u0107 lub nieruchomo\u015B\u0107.",
              "Enter: wykonaj wybran\u0105 czynno\u015B\u0107.",
              "Escape: zamknij bie\u017C\u0105c\u0105 list\u0119.",
              "I: odczytaj pozycje graczy i numery p\u00F3l.",
              "T: odczytaj, czyja jest kolej i na jak\u0105 decyzj\u0119 czeka gra.",
              "C: odczytaj swoj\u0105 got\u00F3wk\u0119.",
              "S: odczytaj finanse graczy.",
              "F: odczytaj kart\u0119 nieruchomo\u015Bci, na kt\u00F3rej stoisz.",
              "D: przejrzyj nieruchomo\u015Bci bez w\u0142a\u015Bciciela.",
              "Shift+D: przejrzyj ca\u0142\u0105 plansz\u0119.",
              "V: przejrzyj w\u0142asne nieruchomo\u015Bci.",
              "Shift+V: przejrzyj nieruchomo\u015Bci innych graczy.",
              "H: otw\u00F3rz list\u0119 nieruchomo\u015Bci, na kt\u00F3rych mo\u017Cesz budowa\u0107.",
              "Shift+H: otw\u00F3rz list\u0119 budynk\u00F3w do sprzedania.",
              "K: otw\u00F3rz list\u0119 nieruchomo\u015Bci do zastawienia.",
              "Shift+K: otw\u00F3rz list\u0119 zastaw\u00F3w do wykupienia.",
              "E: wybierz gracza i przygotuj propozycj\u0119 wymiany.",
              "A: przyjmij otrzyman\u0105 propozycj\u0119 wymiany.",
              "R: odrzu\u0107 otrzyman\u0105 propozycj\u0119 wymiany.",
              "B: podczas rozliczania w\u0142asnego d\u0142ugu og\u0142o\u015B bankructwo; podczas aukcji wpisz w\u0142asn\u0105 kwot\u0119 oferty.",
              "G: podczas aukcji z\u0142\u00F3\u017C podpowiadan\u0105 ofert\u0119.",
              "Spacja: za\u017C\u0105daj czynszu przy r\u0119cznym pobieraniu.",
              "P: zap\u0142a\u0107 za wyj\u015Bcie z wi\u0119zienia.",
              "J: u\u017Cyj posiadanej karty wyj\u015Bcia z wi\u0119zienia.")
          ]
        when "ru"
          [
            rule_section(:aim, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0412 \u00AB\u041C\u043E\u043D\u043E\u043F\u043E\u043B\u0438\u0438\u00BB \u0432\u044B \u043F\u043E\u043A\u0443\u043F\u0430\u0435\u0442\u0435 \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u044C \u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442\u0435 \u0430\u0440\u0435\u043D\u0434\u0443 \u043E\u0442 \u043F\u043E\u043F\u0430\u0432\u0448\u0438\u0445 \u043D\u0430 \u043D\u0435\u0451 \u0438\u0433\u0440\u043E\u043A\u043E\u0432. \u041F\u0440\u0438 \u044D\u0442\u043E\u043C \u043D\u0443\u0436\u043D\u043E \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0442\u044C \u0434\u0435\u043D\u044C\u0433\u0438 \u043D\u0430 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435 \u0440\u0430\u0441\u0445\u043E\u0434\u044B. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439, \u043A\u0442\u043E \u043D\u0435 \u043E\u0431\u0430\u043D\u043A\u0440\u043E\u0442\u0438\u043B\u0441\u044F.",
              "\u0418\u0433\u0440\u0430 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u043D\u0430 \u043D\u0430 \u0434\u0432\u0443\u0445 \u2014 \u0432\u043E\u0441\u044C\u043C\u0435\u0440\u044B\u0445. \u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u043F\u043E\u043B\u0435 Atlantic City \u0438\u0437 \u0441\u043E\u0440\u043E\u043A\u0430 \u043A\u043B\u0435\u0442\u043E\u043A. \u0412\u0441\u0435 \u043D\u0430\u0447\u0438\u043D\u0430\u044E\u0442 \u043D\u0430 \u0441\u0442\u0430\u0440\u0442\u0435 \u0441 1500 \u0434\u043E\u043B\u043B\u0430\u0440\u0430\u043C\u0438."),
            rule_section(:turn, "\u0411\u0440\u043E\u0441\u043E\u043A \u043A\u0443\u0431\u0438\u043A\u043E\u0432 \u0438 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435",
              "\u0412 \u043D\u0430\u0447\u0430\u043B\u0435 \u0441\u0432\u043E\u0435\u0433\u043E \u0445\u043E\u0434\u0430 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0431\u0440\u043E\u0441\u043E\u043A \u043A\u0443\u0431\u0438\u043A\u043E\u0432 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u0418\u0433\u0440\u0430 \u0431\u0440\u043E\u0441\u0438\u0442 \u0434\u0432\u0430 \u043A\u0443\u0431\u0438\u043A\u0430 \u0438 \u043F\u0435\u0440\u0435\u0434\u0432\u0438\u043D\u0435\u0442 \u0432\u0430\u0448\u0443 \u0444\u0438\u0448\u043A\u0443 \u043D\u0430 \u0441\u0443\u043C\u043C\u0443 \u0432\u044B\u043F\u0430\u0432\u0448\u0438\u0445 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0439. \u0414\u0430\u043B\u044C\u0448\u0435 \u0432\u0441\u0451 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u043A\u043B\u0435\u0442\u043A\u0438: \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0432\u044B \u0441\u043C\u043E\u0436\u0435\u0442\u0435 \u043A\u0443\u043F\u0438\u0442\u044C \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u044C \u0438\u043B\u0438 \u0434\u043E\u043B\u0436\u043D\u044B \u0431\u0443\u0434\u0435\u0442\u0435 \u0437\u0430\u043F\u043B\u0430\u0442\u0438\u0442\u044C \u0435\u0451 \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0443.",
              "\u0414\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442\u0441\u044F \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u044E\u0442\u0441\u044F Enter. \u0420\u0430\u0437\u043E\u0431\u0440\u0430\u0432\u0448\u0438\u0441\u044C \u0441\u043E \u0432\u0441\u0435\u043C\u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F\u043C\u0438 \u043D\u0430 \u043A\u043B\u0435\u0442\u043A\u0435, \u0432\u044B \u043F\u0435\u0440\u0435\u0434\u0430\u0451\u0442\u0435 \u0445\u043E\u0434 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443.",
              "\u041E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u043D\u0430 \u0434\u0432\u0443\u0445 \u043A\u0443\u0431\u0438\u043A\u0430\u0445 \u043D\u0430\u0437\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0434\u0443\u0431\u043B\u0435\u043C. \u041F\u043E\u0441\u043B\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F \u0438 \u0440\u0430\u0441\u0447\u0451\u0442\u0430 \u043F\u043E \u043A\u043B\u0435\u0442\u043A\u0435 \u0434\u0443\u0431\u043B\u044C \u0434\u0430\u0451\u0442 \u0435\u0449\u0451 \u043E\u0434\u0438\u043D \u0431\u0440\u043E\u0441\u043E\u043A. \u041D\u043E \u0442\u0440\u0435\u0442\u0438\u0439 \u0434\u0443\u0431\u043B\u044C \u043F\u043E\u0434\u0440\u044F\u0434 \u0441\u0440\u0430\u0437\u0443 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442 \u0432\u0430\u0441 \u0432 \u0442\u044E\u0440\u044C\u043C\u0443 \u0431\u0435\u0437 \u0442\u0440\u0435\u0442\u044C\u0435\u0433\u043E \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0435\u043D\u0438\u044F. \u041F\u043E\u043F\u0430\u0434\u0430\u043D\u0438\u0435 \u0432 \u0442\u044E\u0440\u044C\u043C\u0443 \u0438\u043B\u0438 \u0432\u043E\u0437\u043D\u0438\u043A\u043D\u043E\u0432\u0435\u043D\u0438\u0435 \u0434\u043E\u043B\u0433\u0430 \u043F\u0440\u0435\u043A\u0440\u0430\u0449\u0430\u0435\u0442 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0431\u0440\u043E\u0441\u043A\u0438.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 I \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0438\u0433\u0440\u043E\u043A\u043E\u0432, Shift+D \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u043F\u043E\u043B\u044F, C \u2014 \u0432\u0430\u0448\u0443 \u043D\u0430\u043B\u0438\u0447\u043D\u043E\u0441\u0442\u044C."),
            rule_section(:buying, "\u041F\u043E\u043A\u0443\u043F\u043A\u0430 \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u0438",
              "\u041F\u043E\u043F\u0430\u0432 \u043D\u0430 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0443\u044E \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u044C, \u043C\u043E\u0436\u043D\u043E \u043A\u0443\u043F\u0438\u0442\u044C \u0435\u0451 \u0437\u0430 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u0443\u044E \u0446\u0435\u043D\u0443. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043F\u043E\u043A\u0443\u043F\u043A\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u0415\u0441\u043B\u0438 \u043D\u0435 \u0445\u043E\u0442\u0438\u0442\u0435, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043E\u0442\u043A\u0430\u0437. \u0415\u0441\u043B\u0438 \u0434\u0435\u043D\u0435\u0433 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E, \u043F\u043E\u043A\u0443\u043F\u043A\u0430 \u043F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0441\u044F. \u041D\u0435\u043F\u0440\u043E\u0434\u0430\u043D\u043D\u0430\u044F \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u044C \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u0439.",
              "\u0415\u0441\u0442\u044C \u0442\u0440\u0438 \u0432\u0438\u0434\u0430 \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u0438:",
              "- \u0423\u043B\u0438\u0446\u044B \u043E\u0431\u044A\u0435\u0434\u0438\u043D\u0435\u043D\u044B \u0432 \u0446\u0432\u0435\u0442\u043E\u0432\u044B\u0435 \u0433\u0440\u0443\u043F\u043F\u044B. \u041F\u043E\u043B\u043D\u0430\u044F \u0433\u0440\u0443\u043F\u043F\u0430 \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u0430\u0440\u0435\u043D\u0434\u0443 \u0438 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0441\u0442\u0440\u043E\u0438\u0442\u044C \u0434\u043E\u043C\u0430.",
              "- \u0412\u043E\u043A\u0437\u0430\u043B\u044B \u043F\u0440\u0438\u043D\u043E\u0441\u044F\u0442 \u0442\u0435\u043C \u0431\u043E\u043B\u044C\u0448\u0443\u044E \u0430\u0440\u0435\u043D\u0434\u0443, \u0447\u0435\u043C \u0431\u043E\u043B\u044C\u0448\u0435 \u0438\u0445 \u0443 \u043E\u0434\u043D\u043E\u0433\u043E \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0430.",
              "- \u041F\u0440\u0435\u0434\u043F\u0440\u0438\u044F\u0442\u0438\u044F, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u044D\u043B\u0435\u043A\u0442\u0440\u043E\u0441\u0442\u0430\u043D\u0446\u0438\u044F \u0438 \u0432\u043E\u0434\u043E\u043F\u0440\u043E\u0432\u043E\u0434, \u043D\u0430\u0437\u043D\u0430\u0447\u0430\u044E\u0442 \u0430\u0440\u0435\u043D\u0434\u0443 \u043F\u043E \u0431\u0440\u043E\u0441\u043A\u0443 \u043A\u0443\u0431\u0438\u043A\u043E\u0432. \u041C\u043D\u043E\u0436\u0438\u0442\u0435\u043B\u044C \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u0430 \u043F\u0440\u0435\u0434\u043F\u0440\u0438\u044F\u0442\u0438\u0439 \u0443 \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0430.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 F \u0447\u0438\u0442\u0430\u0435\u0442 \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0443 \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u0438 \u043F\u043E\u0434 \u0432\u0430\u0448\u0435\u0439 \u0444\u0438\u0448\u043A\u043E\u0439: \u0446\u0435\u043D\u0443, \u0430\u0440\u0435\u043D\u0434\u0443, \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0441\u0442\u0440\u043E\u0438\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u0430 \u0438 \u0437\u0430\u043B\u043E\u0433\u0430. \u0421\u043F\u0438\u0441\u043E\u043A \u0441\u0432\u043E\u0438\u0445 \u043E\u0431\u044A\u0435\u043A\u0442\u043E\u0432 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 V, \u0447\u0443\u0436\u0438\u0445 \u2014 Shift+V. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043E\u0431\u044A\u0435\u043A\u0442 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter \u0434\u043B\u044F \u043F\u043E\u0434\u0440\u043E\u0431\u043D\u043E\u0441\u0442\u0435\u0439."),
            rule_section(:rent, "\u0410\u0440\u0435\u043D\u0434\u0430",
              "\u0417\u0430 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0443 \u043D\u0430 \u0447\u0443\u0436\u043E\u043C \u043E\u0431\u044A\u0435\u043A\u0442\u0435 \u0432\u044B \u043F\u043B\u0430\u0442\u0438\u0442\u0435 \u0430\u0440\u0435\u043D\u0434\u0443 \u0435\u0433\u043E \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0443. \u041E\u0431\u044B\u0447\u043D\u043E \u043E\u043D\u0430 \u0432\u0437\u0438\u043C\u0430\u0435\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438. \u041D\u0430 \u0441\u0432\u043E\u0435\u0439 \u0438\u043B\u0438 \u0437\u0430\u043B\u043E\u0436\u0435\u043D\u043D\u043E\u0439 \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u0438 \u043F\u043B\u0430\u0442\u0438\u0442\u044C \u043D\u0435 \u043D\u0443\u0436\u043D\u043E.",
              "\u0410\u0440\u0435\u043D\u0434\u0430 \u0443\u043B\u0438\u0446\u044B \u0443\u043A\u0430\u0437\u0430\u043D\u0430 \u0432 \u0435\u0451 \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0435 \u0438 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u0437\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438. \u0415\u0441\u043B\u0438 \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0443 \u043F\u0440\u0438\u043D\u0430\u0434\u043B\u0435\u0436\u0438\u0442 \u0432\u0435\u0441\u044C \u0446\u0432\u0435\u0442, \u0430 \u043D\u0430 \u044D\u0442\u043E\u0439 \u0443\u043B\u0438\u0446\u0435 \u0435\u0449\u0451 \u043D\u0435\u0442 \u0437\u0434\u0430\u043D\u0438\u0439, \u0435\u0451 \u0431\u0430\u0437\u043E\u0432\u0430\u044F \u0430\u0440\u0435\u043D\u0434\u0430 \u0443\u0434\u0432\u0430\u0438\u0432\u0430\u0435\u0442\u0441\u044F. \u0414\u043E\u043C\u0430 \u0438 \u0433\u043E\u0441\u0442\u0438\u043D\u0438\u0446\u044B \u043F\u043E\u0434\u043D\u0438\u043C\u0430\u044E\u0442 \u0435\u0451 \u0434\u0430\u043B\u044C\u0448\u0435 \u043F\u043E \u0440\u0430\u0441\u0446\u0435\u043D\u043A\u0430\u043C \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0438."),
            rule_section(:events, "\u0421\u0442\u0430\u0440\u0442, \u043D\u0430\u043B\u043E\u0433\u0438 \u0438 \u0441\u043E\u0431\u044B\u0442\u0438\u044F",
              "\u0417\u0430 \u043F\u0440\u043E\u0445\u043E\u0434 \u0447\u0435\u0440\u0435\u0437 \u0441\u0442\u0430\u0440\u0442 \u0432\u044B \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442\u0435 200 \u0434\u043E\u043B\u043B\u0430\u0440\u043E\u0432. \u0422\u043E\u0447\u043D\u0430\u044F \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043D\u0430 \u043D\u0451\u043C \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 400.",
              "\u041D\u0435 \u0432\u0441\u0435 \u043A\u043B\u0435\u0442\u043A\u0438 \u043C\u043E\u0436\u043D\u043E \u043A\u0443\u043F\u0438\u0442\u044C:",
              "- \u041F\u043E\u0434\u043E\u0445\u043E\u0434\u043D\u044B\u0439 \u043D\u0430\u043B\u043E\u0433 \u0441\u0442\u043E\u0438\u0442 200 \u0434\u043E\u043B\u043B\u0430\u0440\u043E\u0432, \u043D\u0430\u043B\u043E\u0433 \u043D\u0430 \u0440\u043E\u0441\u043A\u043E\u0448\u044C \u2014 100.",
              "- \u0411\u0435\u0441\u043F\u043B\u0430\u0442\u043D\u0430\u044F \u043F\u0430\u0440\u043A\u043E\u0432\u043A\u0430 \u0432\u044B\u043F\u043B\u0430\u0447\u0438\u0432\u0430\u0435\u0442 \u0432\u0441\u044E \u043D\u0430\u043A\u043E\u043F\u043B\u0435\u043D\u043D\u0443\u044E \u0441\u0443\u043C\u043C\u0443. \u0412 \u043D\u0435\u0451 \u043F\u043E\u0441\u0442\u0443\u043F\u0430\u044E\u0442 \u043D\u0430\u043B\u043E\u0433\u0438 \u0438 \u043F\u043B\u0430\u0442\u0435\u0436\u0438 \u0431\u0430\u043D\u043A\u0443 \u043F\u043E \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0430\u043C \u0438\u043B\u0438 \u0437\u0430 \u0432\u044B\u0445\u043E\u0434 \u0438\u0437 \u0442\u044E\u0440\u044C\u043C\u044B. \u041F\u043E\u0441\u043B\u0435 \u0432\u044B\u043F\u043B\u0430\u0442\u044B \u043D\u0430\u043A\u043E\u043F\u043B\u0435\u043D\u0438\u0435 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0441 \u043D\u0443\u043B\u044F.",
              "- \u0428\u0430\u043D\u0441 \u0438 \u043E\u0431\u0449\u0435\u0441\u0442\u0432\u0435\u043D\u043D\u0430\u044F \u043A\u0430\u0437\u043D\u0430 \u0434\u0430\u044E\u0442 \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0443 \u0441\u043E\u0431\u044B\u0442\u0438\u044F. \u0418\u0433\u0440\u0430 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442 \u0438 \u0441\u0440\u0430\u0437\u0443 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442 \u0435\u0451 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435.",
              "\u0421\u043E\u0431\u044B\u0442\u0438\u044F \u0431\u044B\u0432\u0430\u044E\u0442 \u0440\u0430\u0437\u043D\u044B\u043C\u0438:",
              "- \u041F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u0434\u0435\u043D\u044C\u0433\u0438 \u0438\u0437 \u0431\u0430\u043D\u043A\u0430 \u0438\u043B\u0438 \u0437\u0430\u043F\u043B\u0430\u0442\u0438\u0442\u044C \u0435\u043C\u0443.",
              "- \u0417\u0430\u043F\u043B\u0430\u0442\u0438\u0442\u044C \u0434\u0440\u0443\u0433\u0438\u043C \u0438\u0433\u0440\u043E\u043A\u0430\u043C \u0438\u043B\u0438 \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u0434\u0435\u043D\u044C\u0433\u0438 \u043E\u0442 \u043A\u0430\u0436\u0434\u043E\u0433\u043E.",
              "- \u041E\u043F\u043B\u0430\u0442\u0438\u0442\u044C \u0440\u0435\u043C\u043E\u043D\u0442 \u0432 \u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E\u0441\u0442\u0438 \u043E\u0442 \u0441\u0432\u043E\u0438\u0445 \u0434\u043E\u043C\u043E\u0432 \u0438 \u0433\u043E\u0441\u0442\u0438\u043D\u0438\u0446.",
              "- \u041F\u0435\u0440\u0435\u0439\u0442\u0438 \u043D\u0430 \u0434\u0440\u0443\u0433\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443. \u041D\u0430 \u043D\u0435\u0439 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0442 \u043E\u0431\u044B\u0447\u043D\u044B\u0435 \u043F\u043E\u043A\u0443\u043F\u043A\u0430, \u0430\u0440\u0435\u043D\u0434\u0430 \u0438\u043B\u0438 \u043D\u0430\u043B\u043E\u0433, \u0435\u0441\u043B\u0438 \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0430 \u043D\u0435 \u0443\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0438\u043D\u043E\u0435.",
              "- \u041E\u0442\u043F\u0440\u0430\u0432\u0438\u0442\u044C\u0441\u044F \u0432 \u0442\u044E\u0440\u044C\u043C\u0443.",
              "- \u041F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0443 \u043E\u0441\u0432\u043E\u0431\u043E\u0436\u0434\u0435\u043D\u0438\u044F \u0438\u0437 \u0442\u044E\u0440\u044C\u043C\u044B \u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u0435\u0451 \u0434\u043E \u043D\u0443\u0436\u043D\u043E\u0433\u043E \u043C\u043E\u043C\u0435\u043D\u0442\u0430.",
              "\u041D\u0435\u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0435\u043D\u0438\u044F \u043C\u0435\u043D\u044F\u044E\u0442 \u0440\u0430\u0441\u0447\u0451\u0442 \u0430\u0440\u0435\u043D\u0434\u044B:",
              "- \u041A\u0430\u0440\u0442\u043E\u0447\u043A\u0430 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0430 \u043A \u0431\u043B\u0438\u0436\u0430\u0439\u0448\u0435\u043C\u0443 \u0432\u043E\u043A\u0437\u0430\u043B\u0443 \u0443\u0434\u0432\u0430\u0438\u0432\u0430\u0435\u0442 \u0435\u0433\u043E \u0430\u0440\u0435\u043D\u0434\u0443.",
              "- \u041F\u0440\u0438 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0435 \u043A \u0431\u043B\u0438\u0436\u0430\u0439\u0448\u0435\u043C\u0443 \u043F\u0440\u0435\u0434\u043F\u0440\u0438\u044F\u0442\u0438\u044E \u0430\u0440\u0435\u043D\u0434\u0430 \u0440\u0430\u0432\u043D\u0430 \u0434\u0435\u0441\u044F\u0442\u0438\u043A\u0440\u0430\u0442\u043D\u043E\u043C\u0443 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0443 \u043D\u043E\u0432\u043E\u0433\u043E \u0431\u0440\u043E\u0441\u043A\u0430 \u0434\u0432\u0443\u0445 \u043A\u0443\u0431\u0438\u043A\u043E\u0432.",
              "\u041F\u043E\u043A\u0443\u043F\u043A\u0430 \u043E\u0431\u044A\u0435\u043A\u0442\u043E\u0432 \u0438 \u0437\u0434\u0430\u043D\u0438\u0439, \u043E\u043F\u0435\u0440\u0430\u0446\u0438\u0438 \u0441 \u0437\u0430\u043B\u043E\u0433\u043E\u043C \u0438 \u0440\u0430\u0441\u0447\u0451\u0442\u044B \u043C\u0435\u0436\u0434\u0443 \u0438\u0433\u0440\u043E\u043A\u0430\u043C\u0438 \u043D\u0435 \u043F\u043E\u043F\u043E\u043B\u043D\u044F\u044E\u0442 \u0431\u0435\u0441\u043F\u043B\u0430\u0442\u043D\u0443\u044E \u043F\u0430\u0440\u043A\u043E\u0432\u043A\u0443."),
            rule_section(:building, "\u0414\u043E\u043C\u0430 \u0438 \u0433\u043E\u0441\u0442\u0438\u043D\u0438\u0446\u044B",
              "\u0423\u043F\u0440\u0430\u0432\u043B\u044F\u0442\u044C \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u044C\u044E \u043C\u043E\u0436\u043D\u043E \u0432 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434 \u0434\u043E \u0431\u0440\u043E\u0441\u043A\u0430. \u0421\u0442\u0440\u043E\u0438\u0442\u044C \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u0442\u043E\u043B\u044C\u043A\u043E \u043D\u0430 \u0443\u043B\u0438\u0446\u0430\u0445 \u0438 \u043F\u0440\u0438 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0438 \u0432\u0441\u0435\u0445 \u0443\u0441\u043B\u043E\u0432\u0438\u0439:",
              "- \u0412\u0430\u043C \u043F\u0440\u0438\u043D\u0430\u0434\u043B\u0435\u0436\u0438\u0442 \u0432\u0441\u044F \u0446\u0432\u0435\u0442\u043E\u0432\u0430\u044F \u0433\u0440\u0443\u043F\u043F\u0430.",
              "- \u041D\u0438 \u043E\u0434\u043D\u0430 \u0443\u043B\u0438\u0446\u0430 \u044D\u0442\u043E\u0439 \u0433\u0440\u0443\u043F\u043F\u044B \u043D\u0435 \u0437\u0430\u043B\u043E\u0436\u0435\u043D\u0430.",
              "- \u0423 \u0432\u0430\u0441 \u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E \u0434\u0435\u043D\u0435\u0433 \u043D\u0430 \u0441\u0442\u0440\u043E\u0438\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u043E.",
              "\u041D\u0430\u0436\u043C\u0438\u0442\u0435 H, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0443\u043B\u0438\u0446\u0443 \u0438\u0437 \u0441\u043F\u0438\u0441\u043A\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E\u0433\u043E \u0441\u0442\u0440\u043E\u0438\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u0430 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u041E\u0434\u043D\u043E \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u043E\u0434\u043D\u043E \u0437\u0434\u0430\u043D\u0438\u0435 \u0437\u0430 \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u0443\u044E \u0446\u0435\u043D\u0443.",
              "\u0417\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0442\u044C \u0433\u0440\u0443\u043F\u043F\u0443 \u043D\u0443\u0436\u043D\u043E \u0440\u0430\u0432\u043D\u043E\u043C\u0435\u0440\u043D\u043E: \u043F\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043C \u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0432\u0442\u043E\u0440\u043E\u0439 \u0434\u043E\u043C, \u043F\u043E\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u043F\u043E \u043E\u0434\u043D\u043E\u043C\u0443 \u043D\u0430 \u0432\u0441\u0435\u0445 \u0443\u043B\u0438\u0446\u0430\u0445. \u0422\u0430\u043A \u0436\u0435 \u0434\u043E\u0439\u0434\u0438\u0442\u0435 \u0434\u043E \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u0434\u043E\u043C\u043E\u0432 \u043D\u0430 \u0443\u043B\u0438\u0446\u0435. \u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0435 \u0441\u0442\u0440\u043E\u0438\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u043E \u0437\u0430\u043C\u0435\u043D\u0438\u0442 \u0438\u0445 \u0433\u043E\u0441\u0442\u0438\u043D\u0438\u0446\u0435\u0439.",
              "\u0412 \u0431\u0430\u043D\u043A\u0435 32 \u0434\u043E\u043C\u0430 \u0438 12 \u0433\u043E\u0441\u0442\u0438\u043D\u0438\u0446. \u0415\u0441\u043B\u0438 \u043D\u0443\u0436\u043D\u044B\u0445 \u0437\u0434\u0430\u043D\u0438\u0439 \u043D\u0435 \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C, \u0436\u0434\u0438\u0442\u0435 \u0438\u0445 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u044F. \u041F\u0440\u0438 \u043F\u043E\u0441\u0442\u0440\u043E\u0439\u043A\u0435 \u0433\u043E\u0441\u0442\u0438\u043D\u0438\u0446\u044B \u0437\u0430\u043C\u0435\u043D\u0451\u043D\u043D\u044B\u0435 \u0447\u0435\u0442\u044B\u0440\u0435 \u0434\u043E\u043C\u0430 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F \u0432 \u0437\u0430\u043F\u0430\u0441."),
            rule_section(:selling, "\u041F\u0440\u043E\u0434\u0430\u0436\u0430 \u0437\u0434\u0430\u043D\u0438\u0439",
              "\u041D\u0430\u0436\u043C\u0438\u0442\u0435 Shift+H, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u043E\u0434\u0430\u0442\u044C \u0437\u0434\u0430\u043D\u0438\u0435 \u0438 \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u0447\u0430\u0441\u0442\u044C \u0434\u0435\u043D\u0435\u0433. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0435\u0433\u043E \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u0411\u0430\u043D\u043A \u0432\u044B\u043F\u043B\u0430\u0442\u0438\u0442 \u043F\u043E\u043B\u043E\u0432\u0438\u043D\u0443 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u0438 \u0441\u0442\u0440\u043E\u0438\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u0430.",
              "\u041F\u0440\u043E\u0434\u0430\u0432\u0430\u0442\u044C \u0442\u043E\u0436\u0435 \u043D\u0443\u0436\u043D\u043E \u0440\u0430\u0432\u043D\u043E\u043C\u0435\u0440\u043D\u043E, \u043D\u0430\u0447\u0438\u043D\u0430\u044F \u0441 \u043D\u0430\u0438\u0431\u043E\u043B\u0435\u0435 \u0437\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u043D\u044B\u0445 \u0443\u043B\u0438\u0446 \u0433\u0440\u0443\u043F\u043F\u044B. \u041F\u0440\u043E\u0434\u0430\u043D\u043D\u0430\u044F \u0433\u043E\u0441\u0442\u0438\u043D\u0438\u0446\u0430 \u043E\u0431\u044B\u0447\u043D\u043E \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u0447\u0435\u0442\u044B\u0440\u044C\u043C\u044F \u0434\u043E\u043C\u0430\u043C\u0438.",
              "\u0415\u0441\u043B\u0438 \u0432 \u0431\u0430\u043D\u043A\u0435 \u043D\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u0434\u043E\u043C\u043E\u0432 \u0434\u043B\u044F \u0437\u0430\u043C\u0435\u043D\u044B \u0433\u043E\u0441\u0442\u0438\u043D\u0438\u0446\u044B, \u0432 \u0441\u043F\u0438\u0441\u043A\u0435 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043F\u0440\u043E\u0434\u0430\u0436\u0443 \u0432\u0441\u0435\u0439 \u0437\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u044D\u0442\u043E\u0433\u043E \u0446\u0432\u0435\u0442\u0430. \u0412\u044B \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u0435 \u043F\u043E\u043B\u043E\u0432\u0438\u043D\u0443 \u0435\u0451 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u0438."),
            rule_section(:mortgages, "\u0417\u0430\u043B\u043E\u0433 \u0438 \u0432\u044B\u043A\u0443\u043F",
              "\u0417\u0430\u043B\u043E\u0433 \u0434\u0430\u0451\u0442 \u0434\u0435\u043D\u044C\u0433\u0438 \u0438\u0437 \u0431\u0430\u043D\u043A\u0430, \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044F \u0437\u0430 \u0432\u0430\u043C\u0438 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0441\u0442\u044C. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 K, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043E\u0431\u044A\u0435\u043A\u0442 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u0412\u044B \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u0435 \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u0443\u044E \u0432 \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0435 \u0441\u0443\u043C\u043C\u0443 \u0437\u0430\u043B\u043E\u0433\u0430, \u043D\u043E \u043F\u0435\u0440\u0435\u0441\u0442\u0430\u043D\u0435\u0442\u0435 \u0441\u043E\u0431\u0438\u0440\u0430\u0442\u044C \u0430\u0440\u0435\u043D\u0434\u0443 \u0441 \u044D\u0442\u043E\u0433\u043E \u043E\u0431\u044A\u0435\u043A\u0442\u0430.",
              "\u041F\u0435\u0440\u0435\u0434 \u0437\u0430\u043B\u043E\u0433\u043E\u043C \u0443\u043B\u0438\u0446\u044B \u043D\u0443\u0436\u043D\u043E \u043F\u0440\u043E\u0434\u0430\u0442\u044C \u0432\u0441\u0435 \u0437\u0434\u0430\u043D\u0438\u044F \u0432\u043E \u0432\u0441\u0435\u0439 \u0435\u0451 \u0446\u0432\u0435\u0442\u043E\u0432\u043E\u0439 \u0433\u0440\u0443\u043F\u043F\u0435.",
              "\u0414\u043B\u044F \u0432\u044B\u043A\u0443\u043F\u0430 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Shift+K, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043E\u0431\u044A\u0435\u043A\u0442 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u0417\u0430\u043F\u043B\u0430\u0442\u0438\u0442\u0435 \u0441\u0443\u043C\u043C\u0443 \u0437\u0430\u043B\u043E\u0433\u0430 \u043F\u043B\u044E\u0441 \u0434\u0435\u0441\u044F\u0442\u044C \u043F\u0440\u043E\u0446\u0435\u043D\u0442\u043E\u0432, \u043E\u043A\u0440\u0443\u0433\u043B\u0451\u043D\u043D\u0443\u044E \u0432\u0432\u0435\u0440\u0445 \u0434\u043E \u0446\u0435\u043B\u043E\u0439 \u0434\u0435\u043D\u0435\u0436\u043D\u043E\u0439 \u0435\u0434\u0438\u043D\u0438\u0446\u044B. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0437\u0430\u043B\u043E\u0433 100 \u0432\u044B\u043A\u0443\u043F\u0430\u0435\u0442\u0441\u044F \u0437\u0430 110. \u041F\u043E\u0441\u043B\u0435 \u0432\u044B\u043A\u0443\u043F\u0430 \u0430\u0440\u0435\u043D\u0434\u0430 \u0441\u043D\u043E\u0432\u0430 \u043F\u043E\u0441\u0442\u0443\u043F\u0430\u0435\u0442."),
            rule_section(:trading, "\u041E\u0431\u043C\u0435\u043D \u043C\u0435\u0436\u0434\u0443 \u0438\u0433\u0440\u043E\u043A\u0430\u043C\u0438",
              "\u041F\u043E\u043B\u0443\u0447\u0430\u0442\u044C \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u044C \u043C\u043E\u0436\u043D\u043E \u0438 \u043E\u0431\u043C\u0435\u043D\u043E\u043C. \u0412 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434 \u0434\u043E \u0431\u0440\u043E\u0441\u043A\u0430 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 E, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0434\u0440\u0443\u0433\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter.",
              "\u0423\u043A\u0430\u0436\u0438\u0442\u0435, \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0434\u0435\u043D\u0435\u0433 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442\u0435 \u0438 \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0445\u043E\u0442\u0438\u0442\u0435 \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C. \u041A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Tab \u043F\u0435\u0440\u0435\u0439\u0434\u0438\u0442\u0435 \u043A \u0441\u043F\u0438\u0441\u043A\u0430\u043C \u043E\u0431\u044A\u0435\u043A\u0442\u043E\u0432 \u043E\u0431\u0435\u0438\u0445 \u0441\u0442\u043E\u0440\u043E\u043D. \u041F\u0440\u043E\u0441\u043C\u0430\u0442\u0440\u0438\u0432\u0430\u0439\u0442\u0435 \u0438\u0445 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043E\u0442\u043C\u0435\u0447\u0430\u0439\u0442\u0435 \u041F\u0440\u043E\u0431\u0435\u043B\u043E\u043C \u0432\u0441\u0451, \u0447\u0442\u043E \u0432\u0445\u043E\u0434\u0438\u0442 \u0432 \u0441\u0434\u0435\u043B\u043A\u0443. \u0412 \u043E\u0434\u043D\u0443 \u0441\u0434\u0435\u043B\u043A\u0443 \u043C\u043E\u0436\u043D\u043E \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043E\u0431\u044A\u0435\u043A\u0442\u043E\u0432 \u0438 \u0434\u043E\u043F\u043B\u0430\u0442\u0443.",
              "\u0417\u0430\u043A\u043E\u043D\u0447\u0438\u0432, \u043F\u0435\u0440\u0435\u0439\u0434\u0438\u0442\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Tab \u043A \u043E\u0442\u043F\u0440\u0430\u0432\u043A\u0435 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u041F\u043E\u043B\u0443\u0447\u0430\u0442\u0435\u043B\u044C \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0435\u0442 \u0435\u0433\u043E \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 A \u0438\u043B\u0438 \u043E\u0442\u043A\u043B\u043E\u043D\u044F\u0435\u0442 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 R. \u0414\u0435\u043D\u044C\u0433\u0438 \u0438 \u043E\u0431\u044A\u0435\u043A\u0442\u044B \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u044F\u0442 \u043A \u043D\u043E\u0432\u044B\u043C \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0430\u043C \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u043E\u0441\u043B\u0435 \u043F\u0440\u0438\u043D\u044F\u0442\u0438\u044F.",
              "\u0414\u043B\u044F \u0441\u0434\u0435\u043B\u043A\u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0442 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u044F:",
              "- \u0417\u0430\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0435 \u043E\u0431\u044A\u0435\u043A\u0442\u044B \u043F\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u0442\u044C \u043D\u0435\u043B\u044C\u0437\u044F.",
              "- \u041D\u0435\u043B\u044C\u0437\u044F \u043F\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u0442\u044C \u0443\u043B\u0438\u0446\u0443, \u0435\u0441\u043B\u0438 \u0433\u0434\u0435-\u043B\u0438\u0431\u043E \u0432 \u0435\u0451 \u0446\u0432\u0435\u0442\u043E\u0432\u043E\u0439 \u0433\u0440\u0443\u043F\u043F\u0435 \u0435\u0441\u0442\u044C \u0437\u0434\u0430\u043D\u0438\u044F. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u0440\u043E\u0434\u0430\u0439\u0442\u0435 \u0437\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0443 \u0432\u0441\u0435\u0433\u043E \u0446\u0432\u0435\u0442\u0430.",
              "- \u041A\u0430\u0436\u0434\u0430\u044F \u0441\u0442\u043E\u0440\u043E\u043D\u0430 \u0434\u043E\u043B\u0436\u043D\u0430 \u0438\u043C\u0435\u0442\u044C \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u044C \u043E\u043F\u043B\u0430\u0442\u0438\u0442\u044C \u0441\u0432\u043E\u044E \u0447\u0430\u0441\u0442\u044C. \u0423\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0438 \u0434\u0435\u043D\u044C\u0433\u0438, \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u043C\u044B\u0435 \u0432 \u0442\u043E\u0439 \u0436\u0435 \u0441\u0434\u0435\u043B\u043A\u0435."),
            rule_section(:jail, "\u0422\u044E\u0440\u044C\u043C\u0430",
              "\u041E\u0431\u044B\u0447\u043D\u0430\u044F \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043D\u0430 \u043A\u043B\u0435\u0442\u043A\u0435 \u0442\u044E\u0440\u044C\u043C\u044B \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0441\u0435\u0449\u0435\u043D\u0438\u0435\u043C. \u0417\u0430\u043A\u043B\u044E\u0447\u0451\u043D\u043D\u044B\u043C \u0432\u044B \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435\u0441\u044C \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u043E \u0443\u043A\u0430\u0437\u0430\u043D\u0438\u044E \u043A\u043B\u0435\u0442\u043A\u0438 \u0438\u043B\u0438 \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0438 \u043B\u0438\u0431\u043E \u043F\u043E\u0441\u043B\u0435 \u0442\u0440\u0451\u0445 \u0434\u0443\u0431\u043B\u0435\u0439 \u043F\u043E\u0434\u0440\u044F\u0434. \u041E\u0442\u043F\u0440\u0430\u0432\u043A\u0430 \u0432 \u0442\u044E\u0440\u044C\u043C\u0443 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442 \u0445\u043E\u0434 \u0438 \u043D\u0435 \u0434\u0430\u0451\u0442 \u0432\u044B\u043F\u043B\u0430\u0442\u044B \u0437\u0430 \u0441\u0442\u0430\u0440\u0442.",
              "\u0412 \u043D\u0430\u0447\u0430\u043B\u0435 \u0445\u043E\u0434\u0430 \u0432 \u0442\u044E\u0440\u044C\u043C\u0435 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B \u0442\u0440\u0438 \u0441\u043F\u043E\u0441\u043E\u0431\u0430 \u0432\u044B\u0439\u0442\u0438:",
              "- \u041D\u0430\u0436\u0430\u0442\u044C P \u0438 \u0437\u0430\u043F\u043B\u0430\u0442\u0438\u0442\u044C 50 \u0434\u043E\u043B\u043B\u0430\u0440\u043E\u0432. \u0417\u0430\u0442\u0435\u043C \u0431\u0440\u043E\u0441\u0438\u0442\u044C \u043A\u0443\u0431\u0438\u043A\u0438 \u0438 \u0434\u0432\u0438\u0433\u0430\u0442\u044C\u0441\u044F \u043E\u0431\u044B\u0447\u043D\u043E.",
              "- \u041F\u0440\u0438 \u043D\u0430\u043B\u0438\u0447\u0438\u0438 \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0438 \u043E\u0441\u0432\u043E\u0431\u043E\u0436\u0434\u0435\u043D\u0438\u044F \u043D\u0430\u0436\u0430\u0442\u044C J \u0438 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0435\u0451. \u041F\u043E\u0441\u043B\u0435 \u044D\u0442\u043E\u0433\u043E \u0442\u043E\u0436\u0435 \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u043E\u0431\u044B\u0447\u043D\u044B\u0439 \u0431\u0440\u043E\u0441\u043E\u043A.",
              "- \u0421\u0440\u0430\u0437\u0443 \u0431\u0440\u043E\u0441\u0438\u0442\u044C \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Enter, \u043F\u044B\u0442\u0430\u044F\u0441\u044C \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u0434\u0443\u0431\u043B\u044C. \u041D\u0430 \u043F\u043E\u043F\u044B\u0442\u043A\u0438 \u043E\u0442\u0432\u043E\u0434\u044F\u0442\u0441\u044F \u0442\u0440\u0438 \u043E\u0447\u0435\u0440\u0435\u0434\u043D\u044B\u0445 \u0445\u043E\u0434\u0430.",
              "\u0422\u044E\u0440\u0435\u043C\u043D\u044B\u0439 \u0434\u0443\u0431\u043B\u044C \u043E\u0441\u0432\u043E\u0431\u043E\u0436\u0434\u0430\u0435\u0442 \u0438 \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0430\u0435\u0442 \u0432\u0430\u0441 \u043D\u0430 \u0432\u044B\u043F\u0430\u0432\u0448\u0443\u044E \u0441\u0443\u043C\u043C\u0443, \u043D\u043E \u043D\u0435 \u0434\u0430\u0451\u0442 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0431\u0440\u043E\u0441\u043A\u0430. \u041F\u043E\u0441\u043B\u0435 \u0442\u0440\u0435\u0442\u044C\u0435\u0439 \u043D\u0435\u0443\u0434\u0430\u0447\u0438 \u0432\u044B \u043F\u043B\u0430\u0442\u0438\u0442\u0435 50 \u0434\u043E\u043B\u043B\u0430\u0440\u043E\u0432 \u0438 \u0434\u0432\u0438\u0436\u0435\u0442\u0435\u0441\u044C \u043F\u043E \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0443 \u044D\u0442\u043E\u0433\u043E \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u0431\u0440\u043E\u0441\u043A\u0430.",
              "\u0412 \u0442\u044E\u0440\u044C\u043C\u0435 \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u043B\u0443\u0447\u0430\u0442\u044C \u0430\u0440\u0435\u043D\u0434\u0443 \u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u044F\u0442\u044C \u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u043E\u043C \u0434\u043E \u0431\u0440\u043E\u0441\u043A\u0430."),
            rule_section(:debt, "\u0414\u043E\u043B\u0433 \u0438 \u0431\u0430\u043D\u043A\u0440\u043E\u0442\u0441\u0442\u0432\u043E",
              "\u0415\u0441\u043B\u0438 \u0434\u0435\u043D\u0435\u0433 \u043D\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u043D\u0430 \u043F\u043B\u0430\u0442\u0451\u0436, \u0432\u043E\u0437\u043D\u0438\u043A\u0430\u0435\u0442 \u0434\u043E\u043B\u0433. \u0412\u043E\u0437\u043D\u0438\u043A\u043D\u0443\u0432 \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0432\u0430\u0448\u0435\u0433\u043E \u0445\u043E\u0434\u0430, \u043E\u043D \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442 \u044D\u0442\u043E\u0442 \u0445\u043E\u0434. \u041F\u043E\u0433\u0430\u0441\u0438\u0442\u044C \u0434\u043E\u043B\u0433 \u043D\u0443\u0436\u043D\u043E \u0432 \u0441\u0432\u043E\u0439 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0445\u043E\u0434, \u0434\u043E \u043D\u043E\u0432\u043E\u0433\u043E \u0431\u0440\u043E\u0441\u043A\u0430.",
              "\u0414\u043B\u044F \u0440\u0430\u0441\u0447\u0451\u0442\u0430 \u043C\u043E\u0436\u043D\u043E \u043F\u0440\u043E\u0434\u0430\u0432\u0430\u0442\u044C \u0437\u0434\u0430\u043D\u0438\u044F, \u0437\u0430\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0442\u044C \u043E\u0431\u044A\u0435\u043A\u0442\u044B \u0438\u043B\u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u0442\u044C \u0434\u0435\u043D\u044C\u0433\u0438 \u043E\u0431\u043C\u0435\u043D\u043E\u043C. \u041F\u043E\u0441\u043B\u0435 \u043F\u043E\u043B\u043D\u043E\u0433\u043E \u043F\u043E\u0433\u0430\u0448\u0435\u043D\u0438\u044F \u0432\u044B \u0441\u043D\u043E\u0432\u0430 \u043C\u043E\u0436\u0435\u0442\u0435 \u0431\u0440\u043E\u0441\u0430\u0442\u044C \u043A\u0443\u0431\u0438\u043A\u0438.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 B \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u0431\u0430\u043D\u043A\u0440\u043E\u0442\u0441\u0442\u0432\u043E \u0438 \u0432\u044B\u0439\u0442\u0438 \u0438\u0437 \u0431\u043E\u0440\u044C\u0431\u044B. \u0411\u0430\u043D\u043A\u0440\u043E\u0442\u0441\u0442\u0432\u043E \u043D\u0430\u0441\u0442\u0443\u043F\u0430\u0435\u0442 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438, \u0435\u0441\u043B\u0438 \u0432 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434 \u0443 \u0432\u0430\u0441 \u0435\u0441\u0442\u044C \u0434\u043E\u043B\u0433, \u043D\u043E \u0443\u0436\u0435 \u043D\u0435\u043B\u044C\u0437\u044F \u043D\u0438 \u043F\u0440\u043E\u0434\u0430\u0442\u044C \u0437\u0434\u0430\u043D\u0438\u0435, \u043D\u0438 \u0437\u0430\u043B\u043E\u0436\u0438\u0442\u044C \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u044C.",
              "\u0411\u0430\u043D\u043A\u0440\u043E\u0442 \u0432\u044B\u0431\u044B\u0432\u0430\u0435\u0442. \u0415\u0441\u043B\u0438 \u043E\u043D \u0434\u043E\u043B\u0436\u0435\u043D \u0434\u0440\u0443\u0433\u043E\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443, \u043A\u0440\u0435\u0434\u0438\u0442\u043E\u0440 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043E\u0441\u0442\u0430\u0432\u0448\u0443\u044E\u0441\u044F \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u044C \u0438 \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0438 \u043E\u0441\u0432\u043E\u0431\u043E\u0436\u0434\u0435\u043D\u0438\u044F \u0438\u0437 \u0442\u044E\u0440\u044C\u043C\u044B; \u0437\u0434\u0430\u043D\u0438\u044F \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0437\u0430 \u043F\u043E\u043B\u043E\u0432\u0438\u043D\u0443 \u0446\u0435\u043D\u044B. \u041F\u0440\u0438 \u0434\u043E\u043B\u0433\u0435 \u0431\u0430\u043D\u043A\u0443 \u043E\u0431\u044A\u0435\u043A\u0442\u044B \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F \u0431\u0430\u043D\u043A\u0443."),
            rule_section(:ending, "\u041A\u043E\u043D\u0435\u0446 \u0438\u0433\u0440\u044B",
              "\u041F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u043D\u0435 \u043E\u0431\u0430\u043D\u043A\u0440\u043E\u0442\u0438\u0432\u0448\u0438\u0439\u0441\u044F \u0438\u0433\u0440\u043E\u043A \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442. \u0412\u043E \u0432\u0440\u0435\u043C\u044F \u043F\u0430\u0440\u0442\u0438\u0438 \u043A\u043B\u0430\u0432\u0438\u0448\u0430 S \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0441\u0440\u0430\u0432\u043D\u0438\u0442\u044C \u0444\u0438\u043D\u0430\u043D\u0441\u044B \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432."),
            rule_section(:boards, "\u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u0433\u0440\u043E\u0432\u044B\u0435 \u043F\u043E\u043B\u044F",
              "\u041F\u0435\u0440\u0435\u0434 \u0438\u0433\u0440\u043E\u0439 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043F\u043E\u043B\u0435 \u0432\u043C\u0435\u0441\u0442\u043E Atlantic City. \u041F\u043E\u043B\u044F \u0440\u0430\u0437\u043B\u0438\u0447\u0430\u044E\u0442\u0441\u044F \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u044F\u043C\u0438 \u0438 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E\u043C \u043A\u043B\u0435\u0442\u043E\u043A, \u0432\u0430\u043B\u044E\u0442\u043E\u0439, \u0433\u0440\u0443\u043F\u043F\u0430\u043C\u0438 \u043E\u0431\u044A\u0435\u043A\u0442\u043E\u0432, \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u044B\u043C\u0438 \u0434\u0435\u043D\u044C\u0433\u0430\u043C\u0438 \u0438 \u0432\u044B\u043F\u043B\u0430\u0442\u043E\u0439 \u0437\u0430 \u0441\u0442\u0430\u0440\u0442.",
              "\u041D\u0430 \u0431\u043E\u043B\u044C\u0448\u0438\u0445 \u043F\u043E\u043B\u044F\u0445 \u0432 \u0431\u0430\u043D\u043A\u0435 \u0442\u0430\u043A\u0436\u0435 \u0431\u043E\u043B\u044C\u0448\u0435 \u0437\u0434\u0430\u043D\u0438\u0439. \u0426\u0435\u043D\u044B, \u0430\u0440\u0435\u043D\u0434\u0443 \u0438 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0441\u0442\u0440\u043E\u0438\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u0430 \u0443\u0437\u043D\u0430\u0432\u0430\u0439\u0442\u0435 \u0438\u0437 \u043A\u0430\u0440\u0442\u043E\u0447\u0435\u043A \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u0438, \u043A\u0430\u043A \u043E\u0431\u044B\u0447\u043D\u043E.",
              "\u041D\u0435\u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043F\u043B\u0430\u0442\u0435\u0436\u0438 \u043F\u0440\u0438\u0432\u044F\u0437\u0430\u043D\u044B \u043A \u0432\u044B\u043F\u043B\u0430\u0442\u0435 \u0437\u0430 \u0441\u0442\u0430\u0440\u0442:",
              "- \u041F\u043E\u0434\u043E\u0445\u043E\u0434\u043D\u044B\u0439 \u043D\u0430\u043B\u043E\u0433 \u0440\u0430\u0432\u0435\u043D \u043E\u0434\u043D\u043E\u0439 \u0442\u0430\u043A\u043E\u0439 \u0432\u044B\u043F\u043B\u0430\u0442\u0435.",
              "- \u041D\u0430\u043B\u043E\u0433 \u043D\u0430 \u0440\u043E\u0441\u043A\u043E\u0448\u044C \u2014 \u0435\u0451 \u043F\u043E\u043B\u043E\u0432\u0438\u043D\u0435.",
              "- \u041E\u0441\u0432\u043E\u0431\u043E\u0436\u0434\u0435\u043D\u0438\u0435 \u0438\u0437 \u0442\u044E\u0440\u044C\u043C\u044B \u2014 \u0447\u0435\u0442\u0432\u0435\u0440\u0442\u0438.",
              "\u041F\u0440\u0430\u0432\u0438\u043B\u0430 \u043F\u043E\u043B\u043D\u044B\u0445 \u0446\u0432\u0435\u0442\u043E\u0432\u044B\u0445 \u0433\u0440\u0443\u043F\u043F, \u0440\u0430\u0432\u043D\u043E\u043C\u0435\u0440\u043D\u043E\u0433\u043E \u0441\u0442\u0440\u043E\u0438\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u0430, \u0437\u0430\u043B\u043E\u0433\u0430 \u0438 \u0431\u0430\u043D\u043A\u0440\u043E\u0442\u0441\u0442\u0432\u0430 \u043D\u0435 \u043C\u0435\u043D\u044F\u044E\u0442\u0441\u044F."),
            rule_section(:auctions, "\u0410\u0443\u043A\u0446\u0438\u043E\u043D\u044B",
              "\u041E\u0431\u044B\u0447\u043D\u043E \u043E\u0442\u043A\u0430\u0437 \u043E\u0442 \u043F\u043E\u043A\u0443\u043F\u043A\u0438 \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u044C \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u0439. \u0412 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u043F\u0435\u0440\u0435\u0434 \u0438\u0433\u0440\u043E\u0439 \u043C\u043E\u0436\u043D\u043E \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0430\u0443\u043A\u0446\u0438\u043E\u043D\u044B \u043D\u0435\u043F\u0440\u043E\u0434\u0430\u043D\u043D\u044B\u0445 \u043E\u0431\u044A\u0435\u043A\u0442\u043E\u0432. \u0423\u0447\u0430\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u043C\u043E\u0433\u0443\u0442 \u0432\u0441\u0435 \u0435\u0449\u0451 \u0438\u0433\u0440\u0430\u044E\u0449\u0438\u0435, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u043E\u0442\u043A\u0430\u0437\u0430\u0432\u0448\u0435\u0433\u043E\u0441\u044F \u043A\u0443\u043F\u0438\u0442\u044C.",
              "\u0412 \u0441\u0432\u043E\u0439 \u0447\u0435\u0440\u0451\u0434 \u043F\u043E\u0432\u044B\u0448\u0430\u0439\u0442\u0435 \u0441\u0442\u0430\u0432\u043A\u0443 \u0438\u043B\u0438 \u043F\u0430\u0441\u0443\u0439\u0442\u0435. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 G \u0434\u0435\u043B\u0430\u0435\u0442 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u043D\u0443\u044E \u0438\u0433\u0440\u043E\u0439 \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u043D\u0443\u044E \u0441\u0442\u0430\u0432\u043A\u0443. \u0414\u043B\u044F \u0441\u0432\u043E\u0435\u0439 \u0441\u0443\u043C\u043C\u044B \u043D\u0430\u0436\u043C\u0438\u0442\u0435 B, \u0432\u0432\u0435\u0434\u0438\u0442\u0435 \u0435\u0451 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u0412\u0432\u043E\u0434\u0438\u0442\u0441\u044F \u043F\u043E\u043B\u043D\u0430\u044F \u0446\u0435\u043D\u0430 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u044F, \u0430 \u043D\u0435 \u043F\u0440\u0438\u0431\u0430\u0432\u043A\u0430 \u043A \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0435\u0439.",
              "\u041F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0434\u043E\u043B\u0436\u043D\u043E \u043F\u0440\u0435\u0432\u044B\u0448\u0430\u0442\u044C \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u0441\u0442\u0430\u0432\u043A\u0443 \u0438 \u0443\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0442\u044C\u0441\u044F \u0432 \u0432\u0430\u0448\u0443 \u043D\u0430\u043B\u0438\u0447\u043D\u043E\u0441\u0442\u044C. \u0414\u043B\u044F \u043F\u0430\u0441\u0430 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0432\u044B\u0445\u043E\u0434 \u0438\u0437 \u0430\u0443\u043A\u0446\u0438\u043E\u043D\u0430 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u0412\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u0432 \u0442\u0435 \u0436\u0435 \u0442\u043E\u0440\u0433\u0438 \u043F\u043E\u0441\u043B\u0435 \u043F\u0430\u0441\u0430 \u043D\u0435\u043B\u044C\u0437\u044F.",
              "\u041A\u043E\u0433\u0434\u0430 \u043D\u0438\u043A\u0442\u043E \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435 \u043F\u043E\u0432\u044B\u0448\u0430\u0435\u0442, \u0430\u0432\u0442\u043E\u0440 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0435\u0439 \u0441\u0442\u0430\u0432\u043A\u0438 \u043F\u043E\u043A\u0443\u043F\u0430\u0435\u0442 \u043E\u0431\u044A\u0435\u043A\u0442 \u0437\u0430 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u043D\u0443\u044E \u0446\u0435\u043D\u0443. \u0415\u0441\u043B\u0438 \u0432\u0441\u0435 \u0441\u043F\u0430\u0441\u043E\u0432\u0430\u043B\u0438 \u0431\u0435\u0437 \u0435\u0434\u0438\u043D\u043E\u0439 \u0441\u0442\u0430\u0432\u043A\u0438, \u043E\u0431\u044A\u0435\u043A\u0442 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0443 \u0431\u0430\u043D\u043A\u0430.",
              "\u0414\u043B\u044F \u0442\u043E\u0440\u0433\u043E\u0432 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u0434\u0430\u0442\u044C \u0432\u0440\u0435\u043C\u044F \u043D\u0430 \u043A\u0430\u0436\u0434\u043E\u0435 \u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u0432 \u0441\u0435\u043A\u0443\u043D\u0434\u0430\u0445. \u041F\u0440\u043E\u0441\u0440\u043E\u0447\u043A\u0430 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043F\u0430\u0441. \u041A\u0430\u0436\u0434\u044B\u0439 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043F\u043E\u043B\u043D\u044B\u0439 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0441\u0440\u043E\u043A; 0 \u043E\u0442\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0435."),
            rule_section(:purchase_variant, "\u041F\u043E\u043A\u0443\u043F\u043A\u0438 \u043F\u043E\u0441\u043B\u0435 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u043A\u0440\u0443\u0433\u0430",
              "\u041C\u043E\u0436\u043D\u043E \u0437\u0430\u043F\u0440\u0435\u0442\u0438\u0442\u044C \u043F\u043E\u043A\u0443\u043F\u043A\u0438 \u043D\u0430 \u043F\u0435\u0440\u0432\u043E\u043C \u043A\u0440\u0443\u0433\u0435. \u0422\u043E\u0433\u0434\u0430 \u043F\u043E\u043A\u0443\u043F\u0430\u0442\u044C \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0443\u044E \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u044C, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u0432\u044B \u043F\u043E\u043F\u0430\u043B\u0438, \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442\u0441\u044F \u043B\u0438\u0448\u044C \u043F\u043E\u0441\u043B\u0435 \u0432\u0430\u0448\u0435\u0433\u043E \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u043F\u0440\u043E\u0445\u043E\u0434\u0430 \u0447\u0435\u0440\u0435\u0437 \u0441\u0442\u0430\u0440\u0442."),
            rule_section(:rent_variants, "\u0412\u0430\u0440\u0438\u0430\u043D\u0442\u044B \u0441\u0431\u043E\u0440\u0430 \u0430\u0440\u0435\u043D\u0434\u044B",
              "\u041F\u0435\u0440\u0435\u0434 \u043F\u0430\u0440\u0442\u0438\u0435\u0439 \u043C\u043E\u0436\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0434\u0432\u0430 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u0430\u0440\u0435\u043D\u0434\u044B:",
              "- \u0415\u0441\u043B\u0438 \u0432\u044B\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u043F\u043B\u0430\u0442\u0435\u0436\u0438, \u0432\u043B\u0430\u0434\u0435\u043B\u0435\u0446 \u0441\u0430\u043C \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0430\u0440\u0435\u043D\u0434\u0443 \u041F\u0440\u043E\u0431\u0435\u043B\u043E\u043C \u0438\u043B\u0438 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u043E\u0442\u043A\u0430\u0437 \u043E\u0442 \u043D\u0435\u0451 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 Enter. \u0418\u0433\u0440\u0430 \u0436\u0434\u0451\u0442 \u044D\u0442\u043E\u0433\u043E \u0440\u0435\u0448\u0435\u043D\u0438\u044F.",
              "- \u041C\u043E\u0436\u043D\u043E \u0437\u0430\u043F\u0440\u0435\u0442\u0438\u0442\u044C \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u0435 \u0430\u0440\u0435\u043D\u0434\u044B \u0432 \u0442\u044E\u0440\u044C\u043C\u0435. \u041F\u043E\u043A\u0430 \u0432\u043B\u0430\u0434\u0435\u043B\u0435\u0446 \u043D\u0435 \u043E\u0441\u0432\u043E\u0431\u043E\u0434\u0438\u0442\u0441\u044F, \u0434\u0440\u0443\u0433\u0438\u0435 \u043F\u043E\u0441\u0435\u0449\u0430\u044E\u0442 \u0435\u0433\u043E \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u044C \u0431\u0435\u0441\u043F\u043B\u0430\u0442\u043D\u043E."),
            rule_section(:event_variants, "\u0412\u044B\u043F\u043B\u0430\u0442\u044B \u0438 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0441\u043E\u0431\u044B\u0442\u0438\u044F",
              "\u0414\u043E\u0441\u0442\u0443\u043F\u043D\u044B \u0438 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F:",
              "- \u0411\u0435\u0437 \u043D\u0430\u043A\u043E\u043F\u043B\u0435\u043D\u0438\u0439 \u0431\u0435\u0441\u043F\u043B\u0430\u0442\u043D\u043E\u0439 \u043F\u0430\u0440\u043A\u043E\u0432\u043A\u0438 \u044D\u0442\u0430 \u043A\u043B\u0435\u0442\u043A\u0430 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0432\u044B\u043F\u043B\u0430\u0447\u0438\u0432\u0430\u0435\u0442, \u0430 \u043F\u043B\u0430\u0442\u0435\u0436\u0438 \u0431\u0430\u043D\u043A\u0443 \u043D\u0435 \u043E\u0442\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0432 \u0435\u0451 \u0444\u043E\u043D\u0434.",
              "- \u0411\u0435\u0437 \u0434\u0432\u043E\u0439\u043D\u043E\u0439 \u0432\u044B\u043F\u043B\u0430\u0442\u044B \u0442\u043E\u0447\u043D\u0430\u044F \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043D\u0430 \u0441\u0442\u0430\u0440\u0442\u0435 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u0441\u0442\u043E\u043B\u044C\u043A\u043E \u0436\u0435, \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043F\u0440\u043E\u0445\u043E\u0434 \u0447\u0435\u0440\u0435\u0437 \u043D\u0435\u0433\u043E.",
              "- \u0421\u0447\u0430\u0441\u0442\u043B\u0438\u0432\u0430\u044F \u0434\u0432\u043E\u0439\u043D\u0430\u044F \u0435\u0434\u0438\u043D\u0438\u0446\u0430 \u0434\u0430\u0451\u0442 \u0437\u0430 \u0434\u0432\u0435 \u0435\u0434\u0438\u043D\u0438\u0446\u044B \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u0443\u044E \u0447\u0435\u0442\u0432\u0435\u0440\u0442\u044C \u0432\u044B\u043F\u043B\u0430\u0442\u044B \u0437\u0430 \u0441\u0442\u0430\u0440\u0442. \u041D\u0430 Atlantic City \u044D\u0442\u043E 50 \u0434\u043E\u043B\u043B\u0430\u0440\u043E\u0432. \u041E\u0431\u044B\u0447\u043D\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u043E \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D\u043E.",
              "- \u041C\u043E\u0436\u043D\u043E \u0443\u0431\u0440\u0430\u0442\u044C \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0438 \u0448\u0430\u043D\u0441\u0430 \u0438 \u043E\u0431\u0449\u0435\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0439 \u043A\u0430\u0437\u043D\u044B. \u0418\u0437 \u043E\u0431\u0435\u0438\u0445 \u043A\u043E\u043B\u043E\u0434 \u0438\u0441\u0447\u0435\u0437\u043D\u0443\u0442 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0434\u0435\u043D\u0435\u0436\u043D\u044B\u0435 \u0441\u043E\u0431\u044B\u0442\u0438\u044F Power Games, \u0430 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043E\u0441\u0442\u0430\u043D\u0443\u0442\u0441\u044F."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0438\u043B\u0438 \u043E\u0431\u044A\u0435\u043A\u0442 \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u0438.",
              "Enter: \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u044C \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435.",
              "Escape: \u0437\u0430\u043A\u0440\u044B\u0442\u044C \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0441\u043F\u0438\u0441\u043E\u043A.",
              "I: \u0443\u0437\u043D\u0430\u0442\u044C \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u0438 \u043D\u043E\u043C\u0435\u0440\u0430 \u043A\u043B\u0435\u0442\u043E\u043A.",
              "T: \u0443\u0437\u043D\u0430\u0442\u044C, \u0447\u044C\u044F \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u0438 \u043A\u0430\u043A\u043E\u0433\u043E \u0440\u0435\u0448\u0435\u043D\u0438\u044F \u0436\u0434\u0451\u0442 \u0438\u0433\u0440\u0430.",
              "C: \u0443\u0437\u043D\u0430\u0442\u044C \u0441\u0432\u043E\u044E \u043D\u0430\u043B\u0438\u0447\u043D\u043E\u0441\u0442\u044C.",
              "S: \u0443\u0437\u043D\u0430\u0442\u044C \u0444\u0438\u043D\u0430\u043D\u0441\u044B \u0438\u0433\u0440\u043E\u043A\u043E\u0432.",
              "F: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0443 \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u0438 \u043F\u043E\u0434 \u0441\u0432\u043E\u0435\u0439 \u0444\u0438\u0448\u043A\u043E\u0439.",
              "D: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0443\u044E \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u044C.",
              "Shift+D: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0432\u0441\u0451 \u043F\u043E\u043B\u0435.",
              "V: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0441\u0432\u043E\u044E \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u044C.",
              "Shift+V: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0447\u0443\u0436\u0443\u044E \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u044C.",
              "H: \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E\u0435 \u0441\u0442\u0440\u043E\u0438\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u043E.",
              "Shift+H: \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043F\u0440\u043E\u0434\u0430\u0436\u0443 \u0437\u0434\u0430\u043D\u0438\u0439.",
              "K: \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043D\u0435\u0434\u0432\u0438\u0436\u0438\u043C\u043E\u0441\u0442\u044C \u0434\u043B\u044F \u0437\u0430\u043B\u043E\u0433\u0430.",
              "Shift+K: \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0437\u0430\u043B\u043E\u0433 \u0434\u043B\u044F \u0432\u044B\u043A\u0443\u043F\u0430.",
              "E: \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0438\u0433\u0440\u043E\u043A\u0430 \u0438 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u0438\u0442\u044C \u043E\u0431\u043C\u0435\u043D.",
              "A: \u043F\u0440\u0438\u043D\u044F\u0442\u044C \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u043D\u043E\u0435 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043E\u0431\u043C\u0435\u043D\u0430.",
              "R: \u043E\u0442\u043A\u043B\u043E\u043D\u0438\u0442\u044C \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u043D\u043E\u0435 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043E\u0431\u043C\u0435\u043D\u0430.",
              "B: \u043F\u0440\u0438 \u043F\u043E\u0433\u0430\u0448\u0435\u043D\u0438\u0438 \u0441\u0432\u043E\u0435\u0433\u043E \u0434\u043E\u043B\u0433\u0430 \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u0431\u0430\u043D\u043A\u0440\u043E\u0442\u0441\u0442\u0432\u043E; \u043D\u0430 \u0430\u0443\u043A\u0446\u0438\u043E\u043D\u0435 \u0432\u0432\u0435\u0441\u0442\u0438 \u0441\u0443\u043C\u043C\u0443 \u0441\u0442\u0430\u0432\u043A\u0438.",
              "G: \u043D\u0430 \u0430\u0443\u043A\u0446\u0438\u043E\u043D\u0435 \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u043D\u0443\u044E \u0441\u0442\u0430\u0432\u043A\u0443.",
              "\u041F\u0440\u043E\u0431\u0435\u043B: \u043F\u043E\u0442\u0440\u0435\u0431\u043E\u0432\u0430\u0442\u044C \u0430\u0440\u0435\u043D\u0434\u0443 \u043F\u0440\u0438 \u0440\u0443\u0447\u043D\u043E\u043C \u0441\u0431\u043E\u0440\u0435.",
              "P: \u043E\u043F\u043B\u0430\u0442\u0438\u0442\u044C \u043E\u0441\u0432\u043E\u0431\u043E\u0436\u0434\u0435\u043D\u0438\u0435 \u0438\u0437 \u0442\u044E\u0440\u044C\u043C\u044B.",
              "J: \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0443 \u043E\u0441\u0432\u043E\u0431\u043E\u0436\u0434\u0435\u043D\u0438\u044F \u0438\u0437 \u0442\u044E\u0440\u044C\u043C\u044B.")
          ]
        end
